local config = {
  str_homestory_N23dianying_90030101_1_dialog_content = "Huff... Huff! Kita harus aman di sini. saya habiskan!",
  str_homestory_N23dianying_90030101_2_dialog_content = "Kita seharusnya menjadi. Menurut petunjuk dari teka-teki terakhir, kita aman selama kita tetap dalam terang.",
  str_homestory_N23dianying_90030101_3_dialog_content = "Ha... Akhirnya aku bisa mengambil nafas.",
