  str_homestory_N23dianying_90030101_23_dialog_content = "Ingin mencobanya? Mungkin sesuatu akan keluar.",
  str_homestory_N23dianying_90030101_24_dialog_content = "L-Jangan!",
  str_homestory_N23dianying_90030101_24X1_dialog_content = "Benar-benar menggantung, Chubb.",
  str_homestory_N23dianying_90030101_25_dialog_content = "Apakah itu topeng hantu dengan topi di sana?",
  str_homestory_N23dianying_90030101_26_dialog_content = "Aku ingin tahu apa yang akan terjadi jika kita memakainya. Akankah kita berubah menjadi makhluk lain?",
  str_homestory_N23dianying_90030101_27_dialog_content = "L-Jangan main-main!",
  str_homestory_N23dianying_90030101_27X1_dialog_content = "Aku ingin menyentuhnya, Chubb!",
  str_homestory_N23dianying_90030101_28_dialog_content = "Apakah itu telepon?",
  str_homestory_N23dianying_90030101_29_dialog_content = "Mungkin itu akan tiba-tiba berdering, dan beberapa suara menakutkan akan menakut-nakuti Anda dari sisi lain!",
  str_homestory_N23dianying_90030101_30_dialog_content = "Ugh! Mari kita tinggal jauh dari itu.",
