  str_homestory_N23dianying_90030101_35X3_dialog_content = "Apakah akan segera dimulai? Chubb.",
  str_homestory_N23dianying_90030101_36_dialog_content = "Pintunya macet!",
  str_homestory_N23dianying_90030101_37_dialog_content = "Tunggu... Seseorang di sana!",
  str_homestory_N23dianying_90030101_38_dialog_content = "Tunggu... Seseorang di sana! Penggemar penguntit lainnya?",
  str_homestory_N23dianying_90030101_39_dialog_content = "Ah! Anda dapat melihat saya?",
  str_homestory_N23dianying_90030101_40_dialog_content = "Oh? Anda dapat melihat saya, pengunjung?",
  str_homestory_N23dianying_90030101_41_dialog_content = "S-Siapa kamu?",
  str_homestory_N23dianying_90030101_42_dialog_content = "Aku hantu yang terjebak di sini.",
  str_homestory_N23dianying_90030101_43_dialog_content = "Aku... Aku adalah hantu yang terikat di sini.",
  str_homestory_N23dianying_90030101_44_dialog_content = "Hantu?",
  str_homestory_N23dianying_90030101_45_dialog_content = "Ah, tolong jangan takut.",
  str_homestory_N23dianying_90030101_46_dialog_content = "Ya, tapi jangan takut. Aku tidak akan menyakitimu.",
  str_homestory_N23dianying_90030101_47_dialog_content = "Saya hantu yang baik, dan saya biasanya tidak terlihat.",
  str_homestory_N23dianying_90030101_48_dialog_content = "Pasti takdir murni yang kita temui hari ini.",
  str_homestory_N23dianying_90030101_49_dialog_content = "Pasti takdir murni yang kita temui hari ini... atau kau kehilangan kewarasanmu.",
  str_homestory_N23dianying_90030101_50_dialog_content = "Oh, dan tidak perlu khawatir tentang lampu yang berkedip itu. Lampu dan pintu di sini banyak yang tidak berfungsi. Staf akan segera datang untuk memperbaikinya.",
  str_homestory_N23dianying_90030101_51_dialog_content = "Tetap tenang dan bersabarlah.",
  str_homestory_N23dianying_90030101_52_dialog_content = "Tetap tenang dan bersabarlah. Mungkin saya bisa menunjukkan beberapa trik sulap, Anda tahu, untuk membantu Anda menghabiskan waktu.",
  str_homestory_N23dianying_90030101_53_dialog_content = "Tak perlu...",
  str_homestory_N23dianying_90030101_54_dialog_content = "Oh, kami sedang memainkan permainan ruang melarikan diri.",
  str_homestory_N23dianying_90030101_55_dialog_content = "Oh... ngomong-ngomong, kita sedang memainkan permainan ruang melarikan diri.",
  str_homestory_N23dianying_90030101_56_dialog_content = "Bahkan jika lampu mati, staf akan segera memperbaikinya.",
  str_homestory_N23dianying_90030101_57_dialog_content = "Tidak ada bahaya yang bisa diperkirakan.",
  str_homestory_N23dianying_90030101_58_dialog_content = "Ya, jadi mengapa tidak duduk saja dan menunggu staf menanganinya?",
  str_homestory_N23dianying_90030101_59_dialog_content = "Ya. Apakah Anda ingin kopi hitam? Oh, salahku, aku lupa bahwa aku sekarang adalah hantu dan tidak bisa lagi menyeduh kopi untukmu.",
  str_homestory_N23dianying_90030101_60_dialog_content = "Baiklah, mari kita duduk dan menunggu staf.",
  str_homestory_N23dianying_90030101_61_dialog_content = "Uhm... Aku akan berdiri. Terima kasih.",
  str_homestory_N23dianying_90030101_62_dialog_content = "Yah, tidak ada yang bisa diduduki seorang wanita.",
  str_homestory_N23dianying_90030101_63_dialog_content = "Anda mungkin hantu, tetapi Anda cukup perhatian.",
  str_homestory_N23dianying_90030101_64_dialog_content = "Jadi apa cerita Anda ... atau keinginan? Mungkin kami bisa membantu?",
  str_homestory_N23dianying_90030101_65_dialog_content = "Betulkah? Itu sangat baik dari Anda.",
  str_homestory_N23dianying_90030101_66_dialog_content = "Betulkah? Kemudian terima kasih atas masalah Anda.",
  str_homestory_N23dianying_90030101_67_dialog_content = "Akan sangat bagus untuk mengingatkan staf untuk memperbaikinya lebih cepat lain kali.",
  str_homestory_N23dianying_90030101_68_dialog_content = "Saya terjebak di sini selama lebih dari seminggu sebelum mereka akhirnya membuka pintu itu.",
  str_homestory_N23dianying_90030101_69_dialog_content = "Hah? Seminggu?",
  str_homestory_N23dianying_90030101_70_dialog_content = "Aku harus pergi. Tolong jaga dirimu.",
  str_homestory_N23dianying_90030101_71_dialog_content = "Sekadar informasi, aku mati di sini.",
  str_homestory_N23dianying_90030101_72_dialog_content = "T-Tunggu sebentar!",
  str_homestory_N23dianying_90030101_73_dialog_content = "Hantu itu... hilang?",
  str_homestory_N23dianying_90030101_74_dialog_content = "Itu hantu sungguhan... dan bukan aktor, kan?",
  str_homestory_N23dianying_90030101_75_dialog_content = "Itu hantu sungguhan... bukan aktor.",
  str_homestory_N23dianying_90030101_76_dialog_content = "Maksudku, kita tidak akan terjebak di sini selama seminggu, kan?",
  str_homestory_N23dianying_90030101_77_dialog_content = "Mungkinkah dia mengatakan yang sebenarnya? Apakah kita akan terjebak di sini selama seminggu?",
  str_homestory_N23dianying_90030101_78_dialog_content = "T-Itu tidak mungkin! Pasti ada yang salah saat itu...",
  str_homestory_N23dianying_90030101_79_dialog_content = "Tentu saja mereka akan sampai ke kita lebih cepat kali ini.",
  str_homestory_N23dianying_90030101_80_dialog_content = "Hei, lampu mulai berkedip lagi... Hah? Sekarang sudah normal kembali.",
  str_homestory_N23dianying_90030101_81_dialog_content = "Melihat? Sudah kubilang!",
  str_homestory_N23dianying_90030101_82_dialog_content = "Hm? Bukankah itu hantu di sana?",
  str_homestory_N23dianying_90030101_83_dialog_content = "Hei, kenapa kamu kembali lagi?",
  str_homestory_N23dianying_90030101_84_dialog_content = "Hai...?",
  str_homestory_N23dianying_90030101_85_dialog_content = "Tunggu! Ini bukan hantu yang sama!",
  str_homestory_N23dianying_90030101_85X1_dialog_content = "Apa?!",
  str_homestory_N23dianying_90030101_85X2_dialog_content = "Aku merinding, Chubb!",
  str_homestory_N23dianying_90030101_86_dialog_content = "Temukan ... Pergi temukan kebenaran ...",
  str_homestory_N23dianying_90030101_87_dialog_content = "Tampaknya ingin kita... memeriksa buku itu.",
  str_homestory_N23dianying_90030101_88_dialog_content = "Ia ingin kita memeriksa buku itu. Aku akrab dengan tatapan penuh gairah dan keinginan seperti itu di matanya.",
  str_homestory_N23dianying_90030101_89_dialog_content = "Itu pasti... tapi... Permisi, apa isi bukunya?",
  str_homestory_N23dianying_90030101_90_dialog_content = "Temukan ... Pergi temukan kebenaran ...",
  str_homestory_N23dianying_90030101_91_dialog_content = "Bisakah Anda mengatakan sesuatu selain itu?",
  str_homestory_N23dianying_90030101_92_dialog_content = "Bukankah aku baru saja memberitahumu? Temukan itu... Cari kebenaran!",
  str_homestory_N23dianying_90030101_93_dialog_content = "Wow! Itu menjadi marah!",
  str_homestory_N23dianying_90030101_94_dialog_content = "Kurasa kita harus memeriksanya.",
  str_homestory_N23dianying_90030101_95_dialog_content = "Itu tugasku...!",
  str_homestory_N23dianying_90030101_96_option_content = "Jurnal",
  str_homestory_N23dianying_90030101_97_dialog_content = "Pemeran utama wanita, Anda membukanya dan menyadarinya sebagai jurnal.",
  str_homestory_N23dianying_90030101_98_dialog_content = "XX.XX.XXXX",
  str_homestory_N23dianying_90030101_99_dialog_content = "Nona Victoria, tolong hukum aku. Aku sangat pantas mendapatkannya.",
  str_homestory_N23dianying_90030101_100_dialog_content = "Lady Victoria, mohon ampuni dosa-dosaku karena aku adalah monster hina…",
  str_homestory_N23dianying_90030101_101_dialog_content = "Saya mencoba meninggalkan Batu Berburu di Soroz dan pergi sendiri.",
  str_homestory_N23dianying_90030101_102_dialog_content = "Tapi itu baru saja kembali dalam waktu singkat!",
  str_homestory_N23dianying_90030101_103_dialog_content = "Apakah ada cara untuk menghilangkannya? Untuk siapa pun yang menonton ini, saya akan membayar Anda harga yang lumayan untuk menyingkirkannya untuk saya.",
  str_homestory_N23dianying_90030101_104_dialog_content = "Hei, tidak ada bantuan pribadi, chubb!",
  str_homestory_N23dianying_90030101_105_dialog_content = "Kami akan berada dalam masalah besar jika ada yang melihat ini, chubb!",
  str_homestory_N23dianying_90030101_106_dialog_content = "I-Apakah ini prop yang tepat?",
  str_homestory_N23dianying_90030101_107_dialog_content = "Sepertinya itu jurnalnya sendiri!",
  str_homestory_N23dianying_90030101_108_dialog_content = "Sulit sekali membayangkannya...",
  str_homestory_N23dianying_90030101_109_dialog_content = "Tanda... Lebih terasa seperti hantu pahit daripada hantu.",
  str_homestory_N23dianying_90030101_110_dialog_content = "Apakah orang-orang di True Order semuanya orang aneh selain aku?",
  str_homestory_N23dianying_90030101_111_dialog_content = "Saya menyesal telah membaca jurnal Anda.",
  str_homestory_N23dianying_90030101_112_dialog_content = "Tidak... Ini salahku, sungguh.",
  str_homestory_N23dianying_90030101_113_dialog_content = "Ini penyesalan dan keselamatan saya.",
  str_homestory_N23dianying_90030101_114_dialog_content = "Ayo! Anda tidak harus membacanya meskipun saya bilang begitu!",
  str_homestory_N23dianying_90030101_115_dialog_content = "Siapa yang menulis naskah bodoh ini!?",
  str_homestory_N23dianying_90030101_116_dialog_content = "Aku tidak tahu apa maksudmu, tapi... kita harus merekam ulang ini setelah memeriksa alat peraga lagi.",
  str_homestory_N23dianying_90030101_117_option_content = "Catatan Kerja",
  str_homestory_N23dianying_90030101_118_dialog_content = "Pemeran utama wanita, Anda membukanya dan mulai membacanya dengan keras.",
  str_homestory_N23dianying_90030101_119_dialog_content = "XX.XX.XXXX",
  str_homestory_N23dianying_90030101_120_dialog_content = "Peralatan di fasilitas tidak berfungsi, mengunci tamu di kamar.",
  str_homestory_N23dianying_90030101_121_dialog_content = "Staf menghabiskan beberapa hari untuk perbaikan darurat, tapi...",
  str_homestory_N23dianying_90030101_122_dialog_content = "Mengapa Anda membaca catatan pekerjaan orang lain?",
  str_homestory_N23dianying_90030101_123_dialog_content = "Ahhhh—!",
  str_homestory_N23dianying_90030101_124_dialog_content = "Kenapa kamu tiba-tiba berteriak!? Dan Anda bisa mengatakan sesuatu yang lain!",
  str_homestory_N23dianying_90030101_125_dialog_content = "Dan ANDA meminta kami untuk membacanya!",
  str_homestory_N23dianying_90030101_126_dialog_content = "Ini masih buku harianku! Anda tidak bisa membacanya begitu saja!",
  str_homestory_N23dianying_90030101_127_dialog_content = "Mengapa Anda membiarkan log pekerjaan Anda dipajang dengan baik di sana? Betapa penasarannya, chubb.",
  str_homestory_N23dianying_90030101_128_dialog_content = "Pasti kru alat peraga, kan? Chubb.",
  str_homestory_N23dianying_90030101_129_dialog_content = "Berhenti bersikap tidak masuk akal. Siapa kamu?",
  str_homestory_N23dianying_90030101_130_dialog_content = "Akulah protagonisnya. Saya memiliki hak untuk menjadi tidak masuk akal! Anda lebih baik menjawab saya, karakter sampingan!",
  str_homestory_N23dianying_90030101_131_dialog_content = "Aku adalah hantu.",
  str_homestory_N23dianying_90030101_132_dialog_content = "Kami tahu itu!",
  str_homestory_N23dianying_90030101_133_dialog_content = "Mengapa Anda tahu itu? Pernahkah Anda melihat satu sebelumnya?",
  str_homestory_N23dianying_90030101_134_dialog_content = "Aku adalah hantu. Ada yang bisa tahu, kan?",
  str_homestory_N23dianying_90030101_135_dialog_content = "Tentu saja!",
  str_homestory_N23dianying_90030101_136_dialog_content = "Benar. Jadi kamu tidak sebodoh kelihatannya.",
  str_homestory_N23dianying_90030101_137_dialog_content = "Kita telah melakukannya. Baru saja, di sini, sebenarnya. Dia bilang dia meninggal di sini karena staf tidak bisa memperbaiki peralatan tepat waktu untuk menyelamatkannya.",
  str_homestory_N23dianying_90030101_138_dialog_content = "Kami yakin melakukannya. Baru saja, di sini, sebenarnya.",
  str_homestory_N23dianying_90030101_139_dialog_content = "Dia bilang dia meninggal karena tukang reparasi yang bodoh.",
  str_homestory_N23dianying_90030101_140_dialog_content = "Oh, betapa malangnya.",
  str_homestory_N23dianying_90030101_141_dialog_content = "Apa? Dia mengatakan itu di belakangku?",
  str_homestory_N23dianying_90030101_142_dialog_content = "Saya tukang reparasi itu.",
  str_homestory_N23dianying_90030101_143_dialog_content = "Saya mencoba untuk membuka pintu, tetapi ada yang tidak beres, jadi saya terjebak di antara dan mati.",
  str_homestory_N23dianying_90030101_144_dialog_content = "Saya mencoba untuk membuka pintu, tetapi ada yang tidak beres, jadi saya terjebak di antara dan mati. Bodoh, bukan?",
  str_homestory_N23dianying_90030101_145_dialog_content = "Uhm... Belasungkawaku.",
  str_homestory_N23dianying_90030101_146_dialog_content = "Nah, lihat sisi terangnya. Jika tukang reparasi bodoh itu sudah mati, bukan dia yang menyelamatkan kita.",
  str_homestory_N23dianying_90030101_147_dialog_content = "Jadi orang lain harus segera datang.",
  str_homestory_N23dianying_90030101_148_dialog_content = "Menyelamatkanmu? Jadi, kenapa kau ada di sini?",
  str_homestory_N23dianying_90030101_149_dialog_content = "Menjelajahi apa yang tersisa dari ruang pelarian itu? Bagaimana santai.",
  str_homestory_N23dianying_90030101_150_dialog_content = "Menjelajahi apa yang tersisa dari ruang pelarian itu? Anda cukup berani, bukan?",
  str_homestory_N23dianying_90030101_151_dialog_content = "Maksud kamu apa? Sisa-sisa ruang pelarian?",
  str_homestory_N23dianying_90030101_152_dialog_content = "Itu persis seperti apa kedengarannya. Tempat ini telah ditutup untuk sementara waktu.",
  str_homestory_N23dianying_90030101_153_dialog_content = "Pikirkan tentang itu. Setelah kecelakaan yang menewaskan dua orang, tidak mungkin tempat ini masih berdiri dan berjalan.",
  str_homestory_N23dianying_90030101_154_dialog_content = "Anda lebih baik pulang. Aku mau tidur sekarang.",
  str_homestory_N23dianying_90030101_155_dialog_content = "Anda lebih baik pulang. Aku akan mencari tahu bagaimana cara menyingkirkan Batu Berburu.",
  str_homestory_N23dianying_90030101_156_dialog_content = "Tunggu... Apa yang kau katakan? Apakah hantu perlu tidur?",
  str_homestory_N23dianying_90030101_157_dialog_content = "Yah, hilang...",
  str_homestory_N23dianying_90030101_158_dialog_content = "Apa yang dia maksud dengan... sudah ditutup?",
  str_homestory_N23dianying_90030101_159_dialog_content = "Mematikan? Tapi kami masuk ke sini dengan tiket kami!",
  str_homestory_N23dianying_90030101_160_dialog_content = "Sebenarnya, jika Anda benar-benar memikirkannya ... Tidak ada seorang pun di sana untuk memeriksa tiket kami, dan kami tidak benar-benar melihat siapa pun kecuali pembunuh gergaji itu.",
  str_homestory_N23dianying_90030101_161_dialog_content = "Saya pikir Anda mengatakan itu karena itu menambah imersi!",
  str_homestory_N23dianying_90030101_162_dialog_content = "Itu yang kupikirkan!",
  str_homestory_N23dianying_90030101_163_dialog_content = "Tapi tidak ada yang datang untuk menyelamatkan kita? Apakah kita benar-benar terjebak di sini...?",
  str_homestory_N23dianying_90030101_164_dialog_content = "Tapi pembunuh gergaji itu... Dia pasti stafnya, kan?",
  str_homestory_N23dianying_90030101_165_dialog_content = "Aku tidak tahu... Aku tidak tahu siapa atau apa dia seharusnya!",
  str_homestory_N23dianying_90030101_166_dialog_content = "Hai! Lampu menyala dan mati lagi! Apakah pintunya masih macet?",
  str_homestory_N23dianying_90030101_167_dialog_content = "Ini semakin tua... Aku tidak takut sama sekali!",
  str_homestory_N23dianying_90030101_168_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  str_homestory_N23dianying_90030101_169_dialog_content = "Mendengarkan! Langkah kaki, dari sisi lain pintu...",
  str_homestory_N23dianying_90030101_170_dialog_content = "Langkah kaki? Dari sisi lain pintu...",
  str_homestory_N23dianying_90030101_171_dialog_content = "Siapa... mungkinkah?",
  str_homestory_N23dianying_90030101_172_option_content = "Gulir Misterius",
  str_homestory_N23dianying_90030101_173_dialog_content = "Pemeran utama wanita membuka gulungan misterius berbentuk aneh ini dan mulai membaca.",
  str_homestory_N23dianying_90030101_174_dialog_content = "Dengarkan aku!",
  str_homestory_N23dianying_90030101_175_dialog_content = "Penguasa Kekosongan Tanpa Akhir.",
  str_homestory_N23dianying_90030101_176_dialog_content = "Sang Penakluk Teror dan Ketakutan.",
  str_homestory_N23dianying_90030101_177_dialog_content = "Putra Kekosongan dan Kekacauan.",
  str_homestory_N23dianying_90030101_178_dialog_content = "Johnny, Raja Iblis Kuliner Hebat!",
  str_homestory_N23dianying_90030101_179_dialog_content = "Saya mengorbankan untuk Anda cacing pasir yang paling lezat dan segar!",
  str_homestory_N23dianying_90030101_180_dialog_content = "Pelayanmu menunggumu!",
  str_homestory_N23dianying_90030101_181_dialog_content = "...",
  str_homestory_N23dianying_90030101_182_dialog_content = "...",
  str_homestory_N23dianying_90030101_183_dialog_content = "Itu bukan urusanku...",
  str_homestory_N23dianying_90030101_184_dialog_content = "Direktur! Jelas ada yang salah dengan alat peraganya!",
  str_homestory_N23dianying_90030101_185_dialog_content = "Kami memiliki banyak ruang untuk perbaikan dalam hal alat peraga, bukan begitu? Chubb.",
  str_homestory_N23dianying_90030101_186_dialog_content = "Hah? Menemukan apa? Apa yang kau bicarakan?",
  str_homestory_N23dianying_90030101_187_dialog_content = "Temukan ... Pergi temukan kebenaran ...",
  str_homestory_N23dianying_90030101_188_dialog_content = "Bukankah aku baru saja memberitahumu? Temukan itu... Cari kebenaran!",
  str_homestory_N23dianying_90030101_189_dialog_content = "Tapi tidak ada ke arah itu!",
  str_homestory_N23dianying_90030101_190_dialog_content = "Tidak? Bagaimana itu mungkin?",
  str_homestory_N23dianying_90030101_191_dialog_content = "Tidak bisakah kamu melihatnya? Di situlah daging dicabik-cabik dan jiwa dilahap.",
  str_homestory_N23dianying_90030101_192_dialog_content = "Tempat di mana saya meletakkan salinan tulisan tangan saya dari dogma.",
  str_homestory_N23dianying_90030101_193_dialog_content = "Saya pikir ada yang salah dengan alat peraga ...",
  str_homestory_N23dianying_90030101_194_dialog_content = "Dan, Nails, Anda tidak mengikuti garis Anda!",
  str_homestory_N23dianying_90030101_195_dialog_content = "maafkan aku... aku akan meminta maaf dan mengaku dengan paku...",
  str_homestory_N23dianying_90030101_196_dialog_content = "Berhenti, berhenti, berhenti! Ini bukan film horor berdarah! Ini akan mengacaukan set juga!",
  str_homestory_N23dianying_90030101_197_dialog_content = "Sulit sekali membayangkannya...",
  str_homestory_N23dianying_90030101_198_dialog_content = "Pasang tutupnya, ya? Berhentilah mempermalukan nama Orde Sejati!",
  str_homestory_N23dianying_90030101_199_dialog_content = "Anda benar-benar tidak bisa melihatnya? Tim alat peraga benar-benar menjatuhkan bola!",
  str_homestory_N23dianying_90030101_200_dialog_content = "Berakting dengan alat peraga imajiner sangat tidak bisa diandalkan!",
  str_homestory_N23dianying_90030101_201_dialog_content = "Semua alat peraga dan set terasa murah. Ini bukan cara untuk membuat film berkualitas!",
  str_homestory_N23dianying_90030101_202_dialog_content = "Nah, Anda ada benarnya.",
  str_homestory_N23dianying_90030101_203_dialog_content = "Pasti ada sesuatu yang salah, terutama ketika Brock berpikir begitu.",
  str_homestory_N23dianying_90030101_204_dialog_content = "Hai! Apa artinya itu!?",
  str_homestory_N23dianying_90030101_205_dialog_content = "Bagaimanapun, lebih baik kita menyiapkan alat peraga dan merekam ulang ini.",
  str_homestory_N23dianying_90030101_206_dialog_content = "Tidak apa-apa. Sebagai pemeran utama wanita, saya sabar. Kami akan kembali setelah set sudah siap.",
  str_homestory_N23dianying_90030201_1_dialog_content = "Apakah ini bagian terdalam dari Gua Naga legendaris—Aula Harta Karun...?",
  str_homestory_N23dianying_90030201_2_dialog_content = "Nah, ini pasti Frost Mirror yang legendaris! Itu dapat menjawab pertanyaan apa pun yang Anda ajukan, dan memiliki kekuatan sihir yang tidak ada habisnya!",
  str_homestory_N23dianying_90030201_2X1_dialog_content = "Nah, Frost Mirror yang legendaris pasti ada di sini! Itu dapat menjawab pertanyaan apa pun yang Anda ajukan, dan memiliki kekuatan sihir yang tidak ada habisnya!",
  str_homestory_N23dianying_90030201_3_dialog_content = "Aku tidak tahu kemana perginya naga penjaga cermin bodoh itu, tapi mendapatkan ini adalah hal yang mudah.",
  str_homestory_N23dianying_90030201_3X1_dialog_content = "Aku tidak tahu kemana perginya naga penjaga cermin bodoh itu, tapi menyelinap ke sini adalah hal yang mudah.",
  str_homestory_N23dianying_90030201_4_dialog_content = "Selama kita benar-benar mengeluarkannya dari sini... Akan ada banyak orang yang hanya meminta untuk membayar mahal untuk itu. Siapa tahu, raja bahkan mungkin memberi saya gelar dan tanah!",
  str_homestory_N23dianying_90030201_4X1_dialog_content = "Atau saya bisa menggunakan kekuatannya untuk menghasilkan banyak uang! Saya akan bergabung dengan daftar orang kaya dalam waktu singkat!",
  str_homestory_N23dianying_90030201_5_dialog_content = "Hahaha... Harta yang sangat langka akhirnya ada di tangan Barbatos, pedagang kriminal terhebat sepanjang masa!",
  str_homestory_N23dianying_90030201_6_dialog_content = "J-Jadi... Ahem, jadi aku akan membantu diriku sendiri.",
  str_homestory_N23dianying_90030201_6X1_dialog_content = "Bagaimana mereka bisa salah? Chubb.",
  str_homestory_N23dianying_90030201_6X2_dialog_content = "Kamu pasti bisa, Revan!",
  str_homestory_N23dianying_90030201_6X3_dialog_content = "Gaji mereka harus dikurangi karena mengatakan hal yang salah, bukan? Chubb.",
  str_homestory_N23dianying_90030201_7_dialog_content = "Oh? Seseorang mendekat. Tapi kenapa mereka ada di Aula Harta Karun...?",
  str_homestory_N23dianying_90030201_7X1_dialog_content = "Apa? Aku bersumpah aku sudah mencari ke mana-mana, tapi tidak ada yang terlihat seperti cermin ajaib.",
  str_homestory_N23dianying_90030201_8_dialog_content = "Oh, lupakan saja, tidak ada waktu untuk itu. Aku akan merunduk di belakang cermin dulu.",
  str_homestory_N23dianying_90030201_8X1_dialog_content = "Tentunya tidak ada orang lain yang bisa mencuri cermin itu...?",
  str_homestory_N23dianying_90030201_9_dialog_content = "Menemukannya! Aku menemukannya-!!",
  str_homestory_N23dianying_90030201_9X1_dialog_content = "Menemukannya! Aku menemukannya-!! Ini pasti tahap terakhir!",
  str_homestory_N23dianying_90030201_10_dialog_content = "Biarkan saya melihat-lihat. Hm... Pohon yang indah berkilauan ini...",
  str_homestory_N23dianying_90030201_10X1_dialog_content = "Biarkan saya melihat pohon berkilauan yang indah ini!",
  str_homestory_N23dianying_90030201_11_dialog_content = "Hmm... Patung Frost Dragon yang sia-sia.",
  str_homestory_N23dianying_90030201_11X1_dialog_content = "Ada juga patung Frost Dragon yang mengesankan ini!",
  str_homestory_N23dianying_90030201_14_dialog_content = "Besar! Butuh banyak kerja keras, tapi kami akhirnya mengalahkan Frost Dragon dan berhasil sampai di sini!",
  str_homestory_N23dianying_90030201_14X1_dialog_content = "Besar! Butuh banyak kerja keras, tapi kami akhirnya mengalahkan Frost Dragon dan berhasil sampai di sini! Jadi di mana pahala tertinggi?",
  str_homestory_N23dianying_90030201_16_dialog_content = "Hah...? Apakah ini boneka beruang? Frost Dragon menyukai hal semacam ini juga?",
  str_homestory_N23dianying_90030201_16X1_dialog_content = "Apa ini? Boneka beruang? Ahahaha! Apakah Frost Dragons benar-benar menyukai hal semacam ini juga?",
  str_homestory_N23dianying_90030201_17_dialog_content = "Aku benar-benar tidak bisa melihatnya...",
  str_homestory_N23dianying_90030201_17X1_dialog_content = "Aku hanya tidak bisa melihatnya!",
  str_homestory_N23dianying_90030201_18_dialog_content = "Tampaknya pada dasarnya cocok dengan rumor.",
  str_homestory_N23dianying_90030201_18X1_dialog_content = "Pada dasarnya sesuai dengan rumor.",
  str_homestory_N23dianying_90030201_19_dialog_content = "Tempat ini seharusnya adalah Hall of Treasures, dijaga oleh Frost Dragon.",
  str_homestory_N23dianying_90030201_19X1_dialog_content = "Tempat ini seharusnya menjadi Aula Harta Karun, dijaga oleh Naga Beku!",
  str_homestory_N23dianying_90030201_22_dialog_content = "Oh? Apa ini...? Ini terlihat agak tidak pada tempatnya.",
  str_homestory_N23dianying_90030201_22X1_dialog_content = "Oh? Apa ini? Ini terlihat benar-benar tidak pada tempatnya.",
  str_homestory_N23dianying_90030201_23_dialog_content = "Meskipun dikatakan bahwa naga juga mengumpulkan beberapa hal aneh, jadi kurasa itu bisa dimengerti.",
  str_homestory_N23dianying_90030201_23X1_dialog_content = "Yah, sepertinya Naga Beku tidak begitu cemerlang. Mungkin sudah salah tempat.",
  str_homestory_N23dianying_90030201_27_dialog_content = "Coba saya lihat... Um, bukankah ini rak pakaian?",
  str_homestory_N23dianying_90030201_27X1_dialog_content = "Biarku lihat. Hah? Ini rak pakaian?",
  str_homestory_N23dianying_90030201_28_dialog_content = "Dan jika Anda melihat pakaian di dalamnya, bukankah itu terlihat seperti pakaian yang mungkin dikenakan oleh karakter dalam dongeng?",
  str_homestory_N23dianying_90030201_28X1_dialog_content = "Dan kenapa ada pakaian perempuan di atasnya? Mungkinkah Frost Dragon bisa berubah menjadi seorang gadis?",
  str_homestory_N23dianying_90030201_37_dialog_content = "Apakah ini benar-benar Aula Harta Karun?",
  str_homestory_N23dianying_90030201_37X1_dialog_content = "Apakah ini benar-benar Aula Harta Karun? Kami tidak melakukan kesalahan?",
  str_homestory_N23dianying_90030201_38_dialog_content = "Tentu saja! Bukankah kita sudah melewati semua kesulitan itu DAN mengalahkan Frost Dragon untuk sampai di sini?!",
  str_homestory_N23dianying_90030201_38X1_dialog_content = "Tentu saja! Bukankah kita sudah melewati semua kesulitan itu DAN mengalahkan Frost Dragon untuk sampai di sini?! Ditambah panduan mengatakan itu ada di sini juga!",
  str_homestory_N23dianying_90030201_45_dialog_content = "Biarku lihat. Hmmm, ada manusia salju yang menggemaskan?!",
  str_homestory_N23dianying_90030201_45X1_dialog_content = "Biarku lihat. Hah? Kenapa ada manusia salju? Mengingatkan saya untuk membuat satu dengan rekan-rekan saya.",
  str_homestory_N23dianying_90030201_46_dialog_content = "Sepertinya tidak akan meleleh. Apakah Frost Dragon membuatnya dengan kekuatannya sendiri?",
  str_homestory_N23dianying_90030201_46X1_dialog_content = "Sepertinya tidak akan meleleh. Cukup mengesankan.",
  str_homestory_N23dianying_90030201_63_dialog_content = "(A-Apa...?! Orang-orang ini benar-benar berhasil mengalahkan Naga Beku? Yang dikatakan mampu mengalahkan seluruh pasukan dalam sekejap mata?)",
  str_homestory_N23dianying_90030201_63X1_dialog_content = "Hah?! Itu luar biasa?",
  str_homestory_N23dianying_90030201_63X2_dialog_content = "Ini adalah hal yang kuat, Chubb.",
  str_homestory_N23dianying_90030201_63X3_dialog_content = "Aku tidak percaya, Chubb.",
  str_homestory_N23dianying_90030201_64_dialog_content = "(Haruskah saya menunjukkan diri saya...? Mungkin jika saya menjelaskan bahwa saya hanya seorang pencuri atau pedagang atau semacamnya, itu akan mencegah mereka berpikir bahwa saya adalah musuh jika ketahuan...)",
  str_homestory_N23dianying_90030201_65_dialog_content = "Akan sangat buruk jika mereka mengira aku monster dan mengejarku...",
  str_homestory_N23dianying_90030201_66_dialog_content = "Tidak harus sesulit ini.",
  str_homestory_N23dianying_90030201_67_dialog_content = "Ini karena Anda secara membabi buta mempercayai seseorang yang Anda temui di labirin.",
  str_homestory_N23dianying_90030201_68_dialog_content = "Pedagang itu mengatakan bahwa dia telah menemukan sejumlah besar peralatan langka di ruang bawah tanah, dan Anda hanya bergegas untuk berdagang dengannya. Tapi itu semua palsu!",
  str_homestory_N23dianying_90030201_69_dialog_content = "Satu episode itu menempatkan kami dalam posisi keuangan yang sangat sulit.",
  str_homestory_N23dianying_90030201_69X1_dialog_content = "Satu episode itu menempatkan kami dalam posisi keuangan yang sangat sulit!",
  str_homestory_N23dianying_90030201_70_dialog_content = "Dan sekarang semua orang tidak bekerja. Bahkan Nona Penyembuh keluar membantu yang terluka untuk membawa sejumlah uang.",
  str_homestory_N23dianying_90030201_71_dialog_content = "Hah? Ah, jangan khawatirkan aku! Saya senang mengobati luka orang lain.",
  str_homestory_N23dianying_90030201_72_dialog_content = "Umm, uh... Itu hanya penilaian sesaat. Aku sudah jauh lebih berhati-hati sejak!",
  str_homestory_N23dianying_90030201_72X1_dialog_content = "Umm, uh... Itu hanya penilaian sesaat.",
  str_homestory_N23dianying_90030201_72X2_dialog_content = "Saya tidak berharap NPC yang tampak tidak berbahaya menjadi ancaman.",
  str_homestory_N23dianying_90030201_73_dialog_content = "Itu tidak benar-benar lebih berhati-hati... Dan setelah itu datang si pencuri, yang mengaku bisa membantu kita melucuti jebakan di dungeon.",
  str_homestory_N23dianying_90030201_73X1_dialog_content = "Ah, benarkah? Setelah itu datanglah pencuri yang mengaku bisa membantu kami melucuti jebakan di dungeon.",
  str_homestory_N23dianying_90030201_74_dialog_content = "Tapi kamu membiarkan dia bergabung dengan kami karena kamu benci berurusan dengan jebakan, hanya untuk bangun dengan semua peralatan hilang?!",
  str_homestory_N23dianying_90030201_74X1_dialog_content = "Anda membiarkan dia bergabung dengan kami karena Anda benci berurusan dengan jebakan, hanya untuk bangun dengan semua peralatan hilang!",
  str_homestory_N23dianying_90030201_75_dialog_content = "Untungnya, itu semua peralatan normal. Perlengkapan canggih ada di pandai besi untuk diperbaiki.",
  str_homestory_N23dianying_90030201_76_dialog_content = "Kalau tidak, akan sangat merepotkan jika harus memulai lagi dari nol.",
  str_homestory_N23dianying_90030201_77_dialog_content = "Aku sudah tahu! Saya tidak akan begitu naif lagi!",
  str_homestory_N23dianying_90030201_77X1_dialog_content = "Aku sudah tahu! Sekali digigit, dua kali malu!",
  str_homestory_N23dianying_90030201_78_dialog_content = "Jika saya pernah bertemu orang yang mengaku sebagai perampok, atau pengusaha, atau pada dasarnya orang yang mencurigakan, saya akan memberikan mereka pemogokan di sana dan kemudian. Simpan saya beberapa kerumitan.",
  str_homestory_N23dianying_90030201_79_dialog_content = "Mmhmm, itu lebih seperti itu.",
  str_homestory_N23dianying_90030201_80_dialog_content = "(... Kedengarannya fatal jika aku menunjukkan diriku. Lebih baik tetap bersembunyi.)",
  str_homestory_N23dianying_90030201_81_dialog_content = "Mari kita lihat cara menggunakan cermin ajaib terlebih dahulu. Sepertinya saya ingat legenda yang mengatakan bahwa cermin bisa menjawab pertanyaan apa pun?",
  str_homestory_N23dianying_90030201_82_dialog_content = "Tampak seperti cermin biasa bagi saya.",
  str_homestory_N23dianying_90030201_82X1_dialog_content = "Tampak seperti cermin biasa bagi saya. Apakah Anda pikir ada saklar atau sesuatu?",
  str_homestory_N23dianying_90030201_83_dialog_content = "Yah, memukulnya tidak menghasilkan apa-apa. Kalian punya ide?",
  str_homestory_N23dianying_90030201_83X1_dialog_content = "Apakah kami menemukan fragmen buku harian dengan informasi yang relevan di jalan? Apa yang kalian pikirkan?",
  str_homestory_N23dianying_90030201_84_dialog_content = "Tidak ada apa-apa! Saya hanya tertarik pada panahan.",
  str_homestory_N23dianying_90030201_84X1_dialog_content = "Tidak ada apa-apa! Saya hanya tertarik pada panahan dan permainan perang.",
  str_homestory_N23dianying_90030201_85_dialog_content = "Tidak ada di sini juga. Saya hanya tertarik pada tindakan terapeutik. Sihir lain membuatku bingung.",
  str_homestory_N23dianying_90030201_85X1_dialog_content = "Tidak ada di sini juga. Saya hanya tertarik pada madu... Maksud saya penggunaan madu untuk terapi.",
  str_homestory_N23dianying_90030201_86_dialog_content = "Bukankah ini kebetulan! Kebetulan saya hanya tertarik untuk mengiris dan memotong monster, tetapi baru saja, minat saya meluas hingga mencakup mengiris dan memotong orang asing yang mencurigakan.",
  str_homestory_N23dianying_90030201_87_dialog_content = "(Hah? Tak satu pun dari mereka belajar sihir?)",
  str_homestory_N23dianying_90030201_88_dialog_content = "(Itu bisa menjadi kesempatanku...)",
  str_homestory_N23dianying_90030201_89_dialog_content = "Hah?! Apakah seseorang bersembunyi di balik cermin ajaib?",
  str_homestory_N23dianying_90030201_89X1_dialog_content = "Hah?! Apakah seseorang di balik cermin ajaib? Musuh tersembunyi?",
  str_homestory_N23dianying_90030201_90_dialog_content = "Selamat datang semuanya!",
  str_homestory_N23dianying_90030201_91_dialog_content = "Penjelajah yang berani.",
  str_homestory_N23dianying_90030201_92_dialog_content = "S-Siapa kamu? Apa yang kamu lakukan di sini?",
  str_homestory_N23dianying_90030201_92X1_dialog_content = "S-Siapa kamu? Apa yang kamu lakukan di sini? Apakah Anda seorang musuh atau semacam telur paskah?",
  str_homestory_N23dianying_90030201_93_dialog_content = "Tidak perlu takut.",
  str_homestory_N23dianying_90030201_94_dialog_content = "Siapa Takut.",
  str_homestory_N23dianying_90030201_95_dialog_content = "Saya adalah roh yang bersemayam di dalam objek ini, Jin dari Cermin.",
  str_homestory_N23dianying_90030201_95X1_dialog_content = "Dia masuk ke dalamnya! Ha ha ha!",
  str_homestory_N23dianying_90030201_95X2_dialog_content = "Itu memalukan, Chubb!",
  str_homestory_N23dianying_90030201_95X3_dialog_content = "Mereka benar-benar tenggelam dalam karakter mereka, Chubb.",
  str_homestory_N23dianying_90030201_96_dialog_content = "Jin dari Cermin...? Saya tidak berpikir saya pernah mendengar Anda disebutkan dalam salah satu legenda.",
  str_homestory_N23dianying_90030201_97_dialog_content = "Cukup benar, cukup tepat. Tapi bagaimanapun juga, legenda hanyalah itu. Ini tidak seperti orang yang pernah benar-benar mengambil Frost Mirror, kan?",
  str_homestory_N23dianying_90030201_97X1_dialog_content = "Cukup benar, cukup tepat. Tapi bagaimanapun juga, legenda hanyalah itu. Ini tidak seperti orang yang pernah benar-benar mengambil Frost Mirror.",
  str_homestory_N23dianying_90030201_98_dialog_content = "Tapi kenapa dia berbicara dengan cara yang lucu?",
  str_homestory_N23dianying_90030201_98X1_dialog_content = "Nada bicara orang ini mencurigakan, jika Anda bertanya kepada saya.",
  str_homestory_N23dianying_90030201_99_dialog_content = "Itu, ah, itu karena aku sudah lama disegel di sini, dengan kekuatan sihir yang tidak mencukupi.",
  str_homestory_N23dianying_90030201_100_dialog_content = "Aku mohon, bawa aku pergi dari sini, jauh dari Naga Beku! Bawa aku pergi ke negeri yang jauh dan tak berpenghuni.",
  str_homestory_N23dianying_90030201_101_dialog_content = "(Setelah itu aku akan menyelinap ke dalam malam dengan cermin ajaibku. Heehee...)",
  str_homestory_N23dianying_90030201_102_dialog_content = "Oh begitu! Lebih baik kita pergi!",
  str_homestory_N23dianying_90030201_103_dialog_content = "Tunggu sebentar! Bagaimana dengan semua bisnis \"terlalu mudah memercayai orang lain\" itu? Setidaknya minta pendapat Nona Penyembuh dulu!",
  str_homestory_N23dianying_90030201_104_dialog_content = "Genie sejati seharusnya bisa memberi kita sedikit demonstrasi kekuatan cermin. Itu sudah cukup untuk membuktikan klaim mereka.",
  str_homestory_N23dianying_90030201_104X1_dialog_content = "Biarkan aku berpikir... Oh!",
  str_homestory_N23dianying_90030201_104X2_dialog_content = "Hah? Apa itu?",
  str_homestory_N23dianying_90030201_104X3_dialog_content = "Waktu berlalu dariku—aku harus menyelesaikan misi yang diberikan ratu kepadaku! Maafkan aku, Direktur!",
  str_homestory_N23dianying_90030201_104X4_dialog_content = "Eh, apa adanya. Kami akan mencari penggantinya.",
  str_homestory_N23dianying_90030201_105_dialog_content = "(... Ini sudah diduga. Namun, saya siap.)",
  str_homestory_N23dianying_90030201_106_dialog_content = "Tapi tentu saja.",
  str_homestory_N23dianying_90030201_107_dialog_content = "Tolong, amati—",
  str_homestory_N23dianying_90030201_108_dialog_content = "Biarkan ada cahaya!",
  str_homestory_N23dianying_90030201_109_dialog_content = "Cermin ajaib.",
  str_homestory_N23dianying_90030201_110_dialog_content = "(Gulungan ajaib yang mahal itu berguna.)",
  str_homestory_N23dianying_90030201_111_dialog_content = "Wow! Ini benar-benar merespons!",
  str_homestory_N23dianying_90030201_112_dialog_content = "Benar saja, Anda tidak bisa begitu saja menyerangnya seperti \"Pahlawan\". Tampaknya membutuhkan Jin dari Cermin untuk bekerja.",
  str_homestory_N23dianying_90030201_112X1_dialog_content = "Benar saja, tebakan liar yang heroik tidak akan berhasil. Sepertinya kita membutuhkan bantuan Genie of the Mirror untuk menggunakannya.",
  str_homestory_N23dianying_90030201_113_dialog_content = "Ohhh... Saya yakin itu akan berhasil dengan beberapa pukulan bagus lagi!",
  str_homestory_N23dianying_90030201_113X1_dialog_content = "Ohhh... Saya yakin itu akan berhasil dengan beberapa pukulan bagus lagi! Banyak game memiliki desain ini!",
  str_homestory_N23dianying_90030201_114_dialog_content = "Saya tidak yakin saya bisa merawat Cermin Ajaib yang rusak ...",
  str_homestory_N23dianying_90030201_115_dialog_content = "Jangan pedulikan itu untuk saat ini! Lanjutkan dan coba kemampuan menjawab pertanyaannya!",
  str_homestory_N23dianying_90030201_116_dialog_content = "Majulah, Nona Penyembuh!",
  str_homestory_N23dianying_90030201_117_dialog_content = "Oke! Oh, Cermin Ajaib, Cermin Ajaib... Apa yang akan menjadi puncak pencapaian penyembuhan saya?",
  str_homestory_N23dianying_90030201_118_dialog_content = "Itu cara bertanya, kan?",
  str_homestory_N23dianying_90030201_119_dialog_content = "Sebentar-",
  str_homestory_N23dianying_90030201_120_dialog_content = "Jawabannya sedang muncul.",
  str_homestory_N23dianying_90030201_121_dialog_content = "Anda akan mendapatkan ketenaran dan kekayaan dengan perawatan Anda terhadap sarang, jatuh tertidur karena penyakitnya.",
  str_homestory_N23dianying_90030201_122_dialog_content = "Tapi prestasi terbesar dan terakhirmu adalah menyembuhkan Raja Iblis dari narkolepsi dan memberinya energi tak terbatas.",
  str_homestory_N23dianying_90030201_123_dialog_content = "Ini memiliki efek samping yang tidak menguntungkan yang menyebabkan dia tetap terjaga selamanya, dan dalam kemarahan dan kelebihan kekuatannya, dia menghancurkan seluruh dunia.",
  str_homestory_N23dianying_90030201_123X1_dialog_content = "Silakan, terus mengada-ada.",
  str_homestory_N23dianying_90030201_123X2_dialog_content = "Apakah mereka berimprovisasi? Chubb.",
  str_homestory_N23dianying_90030201_123X3_dialog_content = "Tidak ada yang akan percaya itu, Chubb!",
  str_homestory_N23dianying_90030201_124_dialog_content = "...",
  str_homestory_N23dianying_90030201_125_dialog_content = "T-Cermin Ajaib tidak selalu benar-benar akurat, kan? Tidak perlu percaya setiap kata.",
  str_homestory_N23dianying_90030201_126_dialog_content = "Aku sebenarnya... Aku cukup kuat untuk membangunkan Raja Iblis??",
  str_homestory_N23dianying_90030201_127_dialog_content = "Heheheh…",
  str_homestory_N23dianying_90030201_128_dialog_content = "Itu tidak lucu, Nona Penyembuh! Kau membuatku takut.",
  str_homestory_N23dianying_90030201_129_dialog_content = "Jangan khawatir tentang saya! Giliran pemanah!",
  str_homestory_N23dianying_90030201_130_dialog_content = "Meh, aku tidak terganggu. Aku bahkan tidak tertarik dengan semua ini.",
  str_homestory_N23dianying_90030201_131_dialog_content = "Biarkan Pahlawan pergi selanjutnya.",
  str_homestory_N23dianying_90030201_132_dialog_content = "Tentu! Cermin Ajaib, Cermin Ajaib, beri tahu saya sekarang betapa hebatnya saya nanti!",
  str_homestory_N23dianying_90030201_133_dialog_content = "Anda... Anda akan meninggalkan gelar Anda sebagai Pahlawan Cahaya, dan jatuh cinta pada makhluk-makhluk kecil yang Anda temui dalam petualangan Anda.",
  str_homestory_N23dianying_90030201_133X1_dialog_content = "Anda... Anda akan meninggalkan gelar Anda sebagai Pahlawan Cahaya, dan mulai mempelajari \"Magimechs\", sejenis robot raksasa.",
  str_homestory_N23dianying_90030201_134_dialog_content = "Anda kemudian akan bekerja dengan mereka untuk mengalahkan semua musuh Gym Leader Anda, satu per satu.",
  str_homestory_N23dianying_90030201_134X1_dialog_content = "Tetapi robot-robot itu, yang awalnya dibuat untuk melindungi orang, menjadi sadar diri dan malah mulai menyerang orang.",
  str_homestory_N23dianying_90030201_135_dialog_content = "Tapi Anda tidak akan... tidak pernah menjadi Juara, dan akhirnya binasa dalam kehinaan yang menyedihkan.",
  str_homestory_N23dianying_90030201_135X1_dialog_content = "Dan Anda akan memulai misi dengan satu-satunya teman robot Anda, untuk menemukan kebenaran di balik pemberontakan Magimech.",
  str_homestory_N23dianying_90030201_135A1_dialog_content = "Ini semakin konyol, Chubb.",
  str_homestory_N23dianying_90030201_135A2_dialog_content = "Itu terdengar akrab?",
  str_homestory_N23dianying_90030201_135A3_dialog_content = "Ini sangat menarik?",
  str_homestory_N23dianying_90030201_136_dialog_content = "Berapa peluangnya...",
  str_homestory_N23dianying_90030201_137_dialog_content = "Anda Cermin Ajaib yang tidak masuk akal! Beraninya kau memfitnah Pahlawanku tercinta!",
  str_homestory_N23dianying_90030201_137X1_dialog_content = "Kamu terus saja mengatakan omong kosong, Cermin! Beraninya kau memfitnah Pahlawan perkasa kita!!",
  str_homestory_N23dianying_90030201_138_dialog_content = "Hah? Tunggu! Tunggu sebentar!",
  str_homestory_N23dianying_90030201_139_dialog_content = "Jadi ITU hubungan Anda—!",
  str_homestory_N23dianying_90030201_139X1_dialog_content = "Tenanglah!",
  str_homestory_N23dianying_90030201_140_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  str_homestory_N23dianying_90030201_141_dialog_content = "Hei, apa yang kamu lakukan? Jika Anda merusak Cermin Ajaib, Jin bisa terluka, atau bahkan terbunuh!",
  str_homestory_N23dianying_90030201_142_dialog_content = "Lihat ekspresi sedihnya!",
  str_homestory_N23dianying_90030201_143_dialog_content = "Sakit... ekspresi?",
  str_homestory_N23dianying_90030201_144_option_content = "Jatuh",
  str_homestory_N23dianying_90030201_145_dialog_content = "Jatuh, Barbatos! \"Buat suara sedih dan pingsan!\"",
  str_homestory_N23dianying_90030201_146_dialog_content = "Ohhh...",
  str_homestory_N23dianying_90030201_147_dialog_content = "... Oh! Penderitaan seperti itu!",
  str_homestory_N23dianying_90030201_148_dialog_content = "aku terluka—",
  str_homestory_N23dianying_90030201_149_dialog_content = "Maaf... aku terlalu impulsif...",
  str_homestory_N23dianying_90030201_149X1_dialog_content = "Maaf... Ini adalah kebodohan masa muda.",
  str_homestory_N23dianying_90030201_150_dialog_content = "Bolehkah saya menyusahkan Anda untuk mencoba, Nona Penyembuh?",
  str_homestory_N23dianying_90030201_151_dialog_content = "Saya akan mencobanya ... Jika hanya untuk mengaduk panci sedikit! Lagipula, akulah yang bisa mengobati raja iblis!",
  str_homestory_N23dianying_90030201_152_dialog_content = "Anda tidak akan membiarkan siapa pun melupakan itu dalam waktu dekat, bukan?",
  str_homestory_N23dianying_90030201_153_dialog_content = "Hmm, itu jelas Cermin Ajaib, tapi kenapa bisa rusak begitu mudah?",
  str_homestory_N23dianying_90030201_154_dialog_content = "Keahlian yang jelek.",
  str_homestory_N23dianying_90030201_155_dialog_content = "II merasakan kekuatan penyembuhan.",
  str_homestory_N23dianying_90030201_156_dialog_content = "Aku, Jin dari Cermin, dipulihkan!",
  str_homestory_N23dianying_90030201_157_dialog_content = "Besar! Dan, eh, permintaan maaf kami.",
  str_homestory_N23dianying_90030201_157X1_dialog_content = "Besar! Dan, eh, maaf soal itu.",
  str_homestory_N23dianying_90030201_158_dialog_content = "Terkadang Archer bahkan lebih terburu-buru dariku. Tapi terlepas dari kekurangan kecil ini, dia memiliki hati yang baik.",
  str_homestory_N23dianying_90030201_159_dialog_content = "Sejak kapan kalian berdua...",
  str_homestory_N23dianying_90030201_160_dialog_content = "Hahahahahaha—",
  str_homestory_N23dianying_90030201_161_dialog_content = "Apakah itu datang dari luar?!",
  str_homestory_N23dianying_90030201_162_dialog_content = "Itu adalah Naga Beku!",
  str_homestory_N23dianying_90030201_163_dialog_content = "Orang bodoh! Apakah Anda benar-benar berpikir Anda bisa membunuh saya?",
  str_homestory_N23dianying_90030201_164_dialog_content = "Kamu telah kehilangan kesempatan untuk mengalahkanku, dan sekarang aku akan pergi—dan membawa Frost Mirror bersamaku!",
  str_homestory_N23dianying_90030201_165_dialog_content = "Rue kebodohan Anda selama sisa hidup Anda! Ha ha ha ha-",
  str_homestory_N23dianying_90030201_166_dialog_content = "...",
  str_homestory_N23dianying_90030201_167_dialog_content = "...",
  str_homestory_N23dianying_90030201_168_dialog_content = "...",
  str_homestory_N23dianying_90030201_169_dialog_content = "Apa yang dikatakan naga bodoh itu??",
  str_homestory_N23dianying_90030201_170_dialog_content = "Itu tidak menyadari bahwa kita memiliki Frost Mirror sekarang.",
  str_homestory_N23dianying_90030201_170X1_dialog_content = "Apa badut besar! KAMI PUNYA Frost Mirror, hahaha!",
  str_homestory_N23dianying_90030201_171_dialog_content = "Tapi sekarang kita tahu Naga Beku mengejar Cermin, kita harus waspada, dan mengawasinya setiap saat.",
  str_homestory_N23dianying_90030201_172_dialog_content = "Jangan khawatir. Kami akan melindungimu.",
  str_homestory_N23dianying_90030201_173_dialog_content = "... Ya ya. Baik. Anda benar sekali.",
  str_homestory_N23dianying_90030201_174_dialog_content = "Sungguh, aku sangat berterima kasih padamu.",
  str_homestory_N23dianying_90030201_175_option_content = "Merasa ada yang tidak beres",
  str_homestory_N23dianying_90030201_176_dialog_content = "Archer, kamu tiba-tiba merasakan ada sesuatu yang salah. \"Orang ini benar-benar mencurigakan.\"",
  str_homestory_N23dianying_90030201_177_dialog_content = "Meskipun cermin, di mana Anda seharusnya tinggal, jelas diserang, Anda tampaknya tidak bereaksi. Bukankah itu aneh?",
  str_homestory_N23dianying_90030201_177X1_dialog_content = "Meskipun cermin, di mana Anda seharusnya tinggal, jelas diserang, Anda tampaknya tidak bereaksi. Itu benar-benar agak aneh.",
  str_homestory_N23dianying_90030201_178_dialog_content = "Apa? Apakah Anda mengatakan bahwa orang ini ...",
  str_homestory_N23dianying_90030201_178X1_dialog_content = "Apa? Maksud Anda — apakah Anda mengatakan bahwa orang ini sama sekali bukan telur paskah?",
  str_homestory_N23dianying_90030201_179_dialog_content = "Tunggu, tunggu sebentar! Aku bisa menjelaskan—aku kesakitan, sangat kesakitan hingga aku pikir aku akan pingsan!",
  str_homestory_N23dianying_90030201_180_dialog_content = "Saya bisa menjelaskan! Tolong, dengarkan saja.",
  str_homestory_N23dianying_90030201_181_dialog_content = "Hahahahahaha—",
  str_homestory_N23dianying_90030201_182_dialog_content = "Apakah itu datang dari luar?!",
  str_homestory_N23dianying_90030201_183_dialog_content = "Itu adalah Naga Beku!",
  str_homestory_N23dianying_90030201_184_dialog_content = "Orang bodoh! Apakah Anda benar-benar berpikir Anda bisa membunuh saya?",
  str_homestory_N23dianying_90030201_185_dialog_content = "Kamu telah kehilangan kesempatan untuk mengalahkanku, dan sekarang aku akan pergi—dan membawa Frost Mirror bersamaku!",
  str_homestory_N23dianying_90030201_186_dialog_content = "Rue kebodohan Anda selama sisa hidup Anda! Ha ha ha ha-",
  str_homestory_N23dianying_90030201_187_dialog_content = "Tidak ada pengampunan—",
  str_homestory_N23dianying_90030201_188_option_content = "Realisasi tiba-tiba",
  str_homestory_N23dianying_90030201_189_dialog_content = "Pahlawan, Anda tiba-tiba menyadari sesuatu yang penting. \"Pedangnya hilang.\"",
  str_homestory_N23dianying_90030201_190_dialog_content = "Tahan, lupakan itu sebentar. Apakah hanya aku atau pedang yang hilang?",
  str_homestory_N23dianying_90030201_191_dialog_content = "Tidak mungkin... Itu masih tidak bisa tertancap di kepala Frost Dragon, kan?",
  str_homestory_N23dianying_90030201_192_dialog_content = "Cepat, mari kita kembali dan mencarinya! Kami dalam masalah besar jika Pahlawan kehilangan pedang!",
  str_homestory_N23dianying_90030201_193_dialog_content = "Oh? Erm... Datang lagi?",
  str_homestory_N23dianying_90030201_194_dialog_content = "Hah? Siapa ini?",
  str_homestory_N23dianying_90030201_194X1_dialog_content = "Hah? Siapa ini? NPC latar belakang?",
  str_homestory_N23dianying_90030201_195_dialog_content = "Lupakan dia. Kita perlu mencari cermin.",
  str_homestory_N23dianying_90030201_195X1_dialog_content = "Lupakan dia. Kita perlu mencari cermin. Saya masih memiliki hal-hal yang harus saya lakukan sesudahnya.",
  str_homestory_N23dianying_90030201_196_dialog_content = "Hmm?",
  str_homestory_N23dianying_90030201_197_dialog_content = "Apa?",
  str_homestory_N23dianying_90030201_198_dialog_content = "Kenapa tidak ada tanda-tanda Cermin Ajaib?",
  str_homestory_N23dianying_90030201_198X1_dialog_content = "Kenapa tidak ada tanda-tanda Cermin Ajaib? Apakah kita belum mencentang kotak arbitrer??",
  str_homestory_N23dianying_90030201_199_dialog_content = "Anda pikir orang ini mencurinya?",
  str_homestory_N23dianying_90030201_200_dialog_content = "Apa?! Aku baru saja akan menanyakan itu padamu.",
  str_homestory_N23dianying_90030201_201_dialog_content = "Tidak menyenangkan menyelinap di sini, dan saya harus memiliki cermin itu untuk menjadi saudagar terkaya di dunia.",
  str_homestory_N23dianying_90030201_202_dialog_content = "Menyelinap masuk? Anda tidak mengira—apakah orang ini semacam pencuri?",
  str_homestory_N23dianying_90030201_203_dialog_content = "Itu benar-benar cukup memicu.",
  str_homestory_N23dianying_90030201_203X1_dialog_content = "Itu membawa kembali beberapa kenangan yang sangat buruk. Aku harus memberimu pelajaran.",
  str_homestory_N23dianying_90030201_204_dialog_content = "Hahahahahaha—",
  str_homestory_N23dianying_90030201_205_dialog_content = "Apakah itu datang dari luar?!",
  str_homestory_N23dianying_90030201_206_dialog_content = "Itu adalah Naga Beku!",
  str_homestory_N23dianying_90030201_207_dialog_content = "Orang bodoh! Apakah Anda benar-benar berpikir Anda bisa mengalahkan saya?",
  str_homestory_N23dianying_90030201_208_dialog_content = "Sekarang, aku akan pergi—dan aku akan membawa Frost Mirror bersamaku! Hal lain... Tempat ini akan runtuh setiap saat sekarang, jadi menyesali kebodohanmu selama sisa hidupmu yang singkat! Ha ha ha ha-",
  str_homestory_N23dianying_90030201_209_dialog_content = "Sial, naga itu lolos.",
  str_homestory_N23dianying_90030201_210_dialog_content = "Dapatkan setelah itu, sekarang!",
  str_homestory_N23dianying_90030201_210X1_dialog_content = "Cepat setelah itu, semuanya! Aku, uh, aku akan menyelesaikan quest yang diberikan ratu padaku!",
  str_homestory_N23dianying_90030201_211_dialog_content = "eh? Hai! Tunggu aku!",
  str_homestory_N23dianying_90030201_211X1_dialog_content = "Akhir ini terlalu slapdash! Chubb!",
  str_homestory_N23dianying_90030201_212_dialog_content = "Aku tidak bisa mengatakan apakah itu hanya sifatmu yang luar biasa atau aktingmu yang fenomenal, tapi runtuh seperti itu adalah suatu kejeniusan, Chubb.",
  str_homestory_N23dianying_90030201_213_dialog_content = "Heyyyy, hanya merasakan sesuatu tidak sekarang? Itu sedikit plot twist yang tiba-tiba, Chubb!",
  str_homestory_N23dianying_90030201_214_dialog_content = "Mengapa Anda tidak menjelaskannya? Lanjutkan!",
  str_homestory_N23dianying_90030201_215_dialog_content = "Nah, di sebagian besar film dan acara televisi, semakin Anda ingin tahu, semakin menegangkan, Chubb.",
  str_homestory_N23dianying_90030201_216_dialog_content = "Frost Dragon sangat mungkin telah terbang bersamanya!",
  str_homestory_N23dianying_90030201_217_dialog_content = "Tapi pedang itu bahkan bukan penyangga, kan? Jadi apa yang terjadi dengan plotnya, Chubb?",
  str_homestory_N23dianying_90030301_1_dialog_content = "Fiuh! Mungkin memakan waktu dua hari, tapi setidaknya semuanya akan datang bersama-sama.",
  str_homestory_N23dianying_90030301_2_dialog_content = "Preman-preman itu gila, menghancurkan tempat artistik seperti itu.",
  str_homestory_N23dianying_90030301_3_dialog_content = "Tapi untungnya, piano itu lolos tanpa cedera ...",
  str_homestory_N23dianying_90030301_3X1_dialog_content = "Kelihatannya mahal, Chubb.",
  str_homestory_N23dianying_90030301_4_dialog_content = "Tapi untungnya, ini juga kesempatan untuk membujuk bos untuk menukar piano dengan panggung.",
  str_homestory_N23dianying_90030301_5_dialog_content = "Setelah itu, saya bisa bernyanyi sepuasnya...",
  str_homestory_N23dianying_90030301_5X1_dialog_content = "Aku ingin mengecilkan volume, Chubb...",
  str_homestory_N23dianying_90030301_6_dialog_content = "Aku tidak percaya bos begitu pelit.",
  str_homestory_N23dianying_90030301_7_dialog_content = "Tidak bersedia membayar perbaikan piano setelah rusak.",
  str_homestory_N23dianying_90030301_8_dialog_content = "DAN mengirimku ke gudang tua untuk beberapa dekorasi kuno...",
  str_homestory_N23dianying_90030301_8X1_dialog_content = "Apa ini?",
  str_homestory_N23dianying_90030301_9_dialog_content = "<color=#e8d9bb>ding—</color>",
  str_homestory_N23dianying_90030301_10_dialog_content = "Maaf, tapi kami tutup—",
  str_homestory_N23dianying_90030301_11_dialog_content = "Hah? Anda lagi?!",
  str_homestory_N23dianying_90030301_12_dialog_content = "Sekarang, sekarang. Itu bukan cara untuk menyambut pelanggan, Tn. Bartender.",
  str_homestory_N23dianying_90030301_12X1_dialog_content = "Kita bertemu lagi, anak bartender.",
  str_homestory_N23dianying_90030301_13_dialog_content = "Saya memiliki beberapa hal mendesak untuk didiskusikan dengan seorang teman lama hari ini, jadi dua gelas Umbraton Encounter, jika Anda mau berbaik hati.",
  str_homestory_N23dianying_90030301_13X1_dialog_content = "Saya membawa seorang teman lama ke sini untuk membahas bisnis hari ini, jadi tolong dua gelas Rediesel Special.",
  str_homestory_N23dianying_90030301_14_dialog_content = "segar keluar. Maaf.",
  str_homestory_N23dianying_90030301_15_dialog_content = "Anda dapat berterima kasih kepada antek-antek gila Anda untuk itu, datang ke sini beberapa hari yang lalu dan menghancurkan tempat itu!",
  str_homestory_N23dianying_90030301_16_dialog_content = "Oh, itu sangat memalukan. Sepertinya saya tidak akan bisa menawari Anda minuman pada kesempatan ini.",
  str_homestory_N23dianying_90030301_16X1_dialog_content = "Oh itu benar. Ada itu... insiden.",
  str_homestory_N23dianying_90030301_17_dialog_content = "Anda ada di sana saat itu terjadi! Jangan main-main denganku!",
  str_homestory_N23dianying_90030301_17X1_dialog_content = "Haruskah kita mencoba di tempat lain?",
  str_homestory_N23dianying_90030301_18_dialog_content = "Tidak apa-apa. Kami hanya akan menyelesaikan kontrak. Mari kita selesaikan.",
  str_homestory_N23dianying_90030301_19_dialog_content = "Ngomong-ngomong, bisakah kamu meminta bartender untuk mengubah musiknya menjadi sesuatu yang lebih... halus?",
  str_homestory_N23dianying_90030301_20_dialog_content = "Pilihan musik Anda menyisakan banyak hal yang diinginkan.",
  str_homestory_N23dianying_90030301_21_dialog_content = "Apa kaubilang?!",
  str_homestory_N23dianying_90030301_22_dialog_content = "Seluruh tempat ini membutuhkan perubahan, sebenarnya.",
  str_homestory_N23dianying_90030301_23_dialog_content = "Apa kaubilang?!",
  str_homestory_N23dianying_90030301_24_dialog_content = "Aku punya orang-orang Anda berjuang di sini untuk berterima kasih untuk itu juga.",
  str_homestory_N23dianying_90030301_25_dialog_content = "Merusak semua dekorasi sebelumnya dan bahkan menghancurkan perabotan!",
  str_homestory_N23dianying_90030301_26_dialog_content = "Baik. Biarkan saya kembali kepada Anda tentang itu nanti.",
  str_homestory_N23dianying_90030301_27_dialog_content = "Dekorasi di sini sedikit... Yah, itu sangat buruk.",
  str_homestory_N23dianying_90030301_28_dialog_content = "Saya tidak ingin tinggal di sini lebih lama dari yang diperlukan.",
  str_homestory_N23dianying_90030301_29_dialog_content = "Minta saja bartender untuk mengubah catatannya.",
  str_homestory_N23dianying_90030301_29X1_dialog_content = "Ha ha ha! Tolong, jangan pedulikan temanku. Ini hanya bagaimana dia berbicara.",
  str_homestory_N23dianying_90030301_30_dialog_content = "Kami juga berteman baik dengan bos di sini. Aku yakin dia tidak akan keberatan.",
  str_homestory_N23dianying_90030301_30X1_dialog_content = "Saya berteman baik dengan bos Anda. Dia tidak akan mengatakan apa-apa jika saya mengambil sedikit ruang di sini.",
  str_homestory_N23dianying_90030301_30X2_dialog_content = "Aku akan menjelaskan semuanya padanya nanti. Anda hanya melompat dan mengubah musik.",
  str_homestory_N23dianying_90030301_31_dialog_content = "Er... B-Bos?",
  str_homestory_N23dianying_90030301_32_dialog_content = "... Baik. Saya mendapatkannya.",
  str_homestory_N23dianying_90030301_33_dialog_content = "Drat. Menggunakan bos saya sendiri untuk mengancam saya.",
  str_homestory_N23dianying_90030301_34_dialog_content = "Tempat ini tidak akan menjadi apa-apa selain tempat nongkrong geng pada tingkat ini.",
  str_homestory_N23dianying_90030301_35_dialog_content = "Aku harus memikirkan cara untuk menghentikan mereka datang lagi.",
  str_homestory_N23dianying_90030301_36_dialog_content = "Saya tahu! Melihat pria paling elegan ini menyukai lingkungannya yang kaku, saya baru saja mencatat—",
  str_homestory_N23dianying_90030301_37_dialog_content = "Maaf, ini bukan yang kita sepakati. aku tidak bisa—",
  str_homestory_N23dianying_90030301_38_dialog_content = "Hah? Apa yang masuk ke bartender? Musik ini-",
  str_homestory_N23dianying_90030301_38X1_dialog_content = "Aku sangat bersemangat, Chubb.",
  str_homestory_N23dianying_90030301_39_dialog_content = "Aku akan membuatnya mematikannya.",
  str_homestory_N23dianying_90030301_39X1_dialog_content = "Wow, anak itu benar-benar memainkan sesuatu yang saya suka.",
  str_homestory_N23dianying_90030301_39X2_dialog_content = "Tapi mungkin sedikit keras untuk Anda. Aku akan membuatnya mematikannya.",
  str_homestory_N23dianying_90030301_40_dialog_content = "Tidak apa-apa.",
  str_homestory_N23dianying_90030301_41_dialog_content = "Melodi dan ritmenya... Ini mengingatkanku saat kami biasa tampil bersama dalam tur.",
  str_homestory_N23dianying_90030301_42_dialog_content = "Apakah kita sedang menuju kilas balik, Chubb?!",
  str_homestory_N23dianying_90030301_43_dialog_content = "Jadi Anda ingat hari-hari itu.",
  str_homestory_N23dianying_90030301_44_dialog_content = "Saya tahu jalan kami berbeda dari waktu ke waktu, karena kami mengambil tanggung jawab yang berbeda.",
  str_homestory_N23dianying_90030301_45_dialog_content = "Meskipun saya memahami posisi kami yang berbeda, terkadang saya masih merasa emosional.",
  str_homestory_N23dianying_90030301_46_dialog_content = "Iya, aku juga.",
  str_homestory_N23dianying_90030301_47_dialog_content = "... Kamu tahu apa? Biarkan saya kembali dan mencoba untuk menyelesaikan sesuatu dengan kontrak.",
  str_homestory_N23dianying_90030301_47X1_dialog_content = "... Dan saat kunci pas Rediesel Anda merampok kargo kami.",
  str_homestory_N23dianying_90030301_47X2_dialog_content = "Jangan lupa saat Shadowlord mengirimku mengejarmu, dan aku mengejarmu melewati Gurun Rediesel selama tiga hari tiga malam penuh!",
  str_homestory_N23dianying_90030301_47X3_dialog_content = "Hei, ayolah! Bukankah kita dimaksudkan untuk membuat film? Ada apa dengan keseriusan tiba-tiba?",
  str_homestory_N23dianying_90030301_47X4_dialog_content = "... Maaf. Saya hanya melihat merah setiap kali saya harus melihat wajahnya.",
  str_homestory_N23dianying_90030301_47X5_dialog_content = "Dimana naskahnya?",
  str_homestory_N23dianying_90030301_47X6_dialog_content = "Kenapa bagian ini tidak dipotong, Chubb?!",
  str_homestory_N23dianying_90030301_47X7_dialog_content = "Oh ya, jadi bagaimana kalau aku kembali dan mencoba menyelesaikan kontrak.",
  str_homestory_N23dianying_90030301_48_dialog_content = "Lihat itu sebagai membantu teman lama keluar.",
  str_homestory_N23dianying_90030301_49_dialog_content = "Semudah itu, Chubb?",
  str_homestory_N23dianying_90030301_50_dialog_content = "Yah, aku benar-benar berterima kasih.",
  str_homestory_N23dianying_90030301_51_dialog_content = "Wow, saya tidak pernah tahu Anda begitu mahir membaca ruangan! Kami harus berterima kasih atas keberhasilan negosiasi ini!",
  str_homestory_N23dianying_90030301_52_dialog_content = "Anda pasti sudah tahu tentang mantan band kami, the Rockin' Dragons, sebelum memilih rekaman itu, kan?",
  str_homestory_N23dianying_90030301_52X1_dialog_content = "Ah, benarkah? Terima kasih banyak!",
  str_homestory_N23dianying_90030301_52X2_dialog_content = "Wow, saya tidak pernah tahu Anda begitu mahir membaca ruangan! Kami harus berterima kasih atas keberhasilan negosiasi ini!",
  str_homestory_N23dianying_90030301_52X3_dialog_content = "Anda pasti sudah tahu tentang mantan band kami, the Rockin' Dragons, sebelum memilih rekaman itu, kan?",
  str_homestory_N23dianying_90030301_53_dialog_content = "Chu! Kesalahpahaman yang sangat besar, Chubb!",
  str_homestory_N23dianying_90030301_54_dialog_content = "aku tidak—",
  str_homestory_N23dianying_90030301_55_dialog_content = "Melihat bartender itu membuktikan dirinya sangat andal, bisakah saya mengajukan permintaan lain?",
  str_homestory_N23dianying_90030301_56_dialog_content = "Di sini saya memiliki pesan yang paling rahasia dan sangat penting. Nanti akan ada perantara untuk mengambilnya.",
  str_homestory_N23dianying_90030301_56X1_dialog_content = "Nah, sudah jelas mengapa bos memilih Anda untuk mengelola tempat ini. Kerja bagus!",
  str_homestory_N23dianying_90030301_56X2_dialog_content = "Melihat bartender itu membuktikan dirinya sangat andal, bisakah saya mengajukan permintaan lain?",
  str_homestory_N23dianying_90030301_56X3_dialog_content = "Di sini saya memiliki pesan yang paling rahasia dan sangat penting. Nanti akan ada perantara untuk mengambilnya.",
  str_homestory_N23dianying_90030301_57_dialog_content = "Tunggu, aku tidak—",
  str_homestory_N23dianying_90030301_58_dialog_content = "Jangan khawatir! Ini benar-benar sangat sederhana.",
  str_homestory_N23dianying_90030301_59_dialog_content = "Kontak akan menggunakan kata kode \"Beauty Under the Moon.\" Serahkan saja surat itu ketika Anda mendengarnya.",
  str_homestory_N23dianying_90030301_60_dialog_content = "Aku punya urusan lain yang harus kuurus, jadi aku akan pergi.",
  str_homestory_N23dianying_90030301_60X1_dialog_content = "Jangan khawatir! Ini benar-benar sangat sederhana.",
  str_homestory_N23dianying_90030301_60X2_dialog_content = "Kontak akan menggunakan kata kode \"Beauty Under the Moon.\" Serahkan saja surat itu ketika Anda mendengarnya.",
  str_homestory_N23dianying_90030301_60X3_dialog_content = "Saya masih memiliki hal-hal yang sangat penting untuk diperhatikan, jadi saya akan pergi.",
  str_homestory_N23dianying_90030301_61_dialog_content = "Hai! Saya belum selesai!",
  str_homestory_N23dianying_90030301_62_dialog_content = "Biarkan orang menyelesaikannya, Chubb!",
  str_homestory_N23dianying_90030301_63_dialog_content = "Sungguh... Setiap orang dari orang-orang ini...",
  str_homestory_N23dianying_90030301_64_dialog_content = "<color=#e8d9bb>ding—</color>",
  str_homestory_N23dianying_90030301_65_dialog_content = "Sekarang siapa itu?! Apakah mereka tidak melihat tanda \"TUTUP\" di pintu?",
  str_homestory_N23dianying_90030301_66_dialog_content = "Sheriff menelepon! Maaf mengganggu, tapi saya di sini tentang perkelahian yang pecah di sini beberapa hari yang lalu.",
  str_homestory_N23dianying_90030301_66X1_dialog_content = "Sheriff menelepon! Maaf mengganggu, tapi saya di sini tentang perkelahian yang pecah di sini beberapa hari yang lalu.",
  str_homestory_N23dianying_90030301_67_dialog_content = "Apakah pemiliknya ada di sekitar?",
  str_homestory_N23dianying_90030301_67X1_dialog_content = "Apakah pemiliknya ada di sekitar?",
  str_homestory_N23dianying_90030301_68_dialog_content = "Sheriff? Waktu yang tepat!",
  str_homestory_N23dianying_90030301_69_dialog_content = "Saya bartender di sini, dan saya adalah saksi mata diskusi kriminal barusan. Mereka bahkan memberi saya surat rahasia.",
  str_homestory_N23dianying_90030301_70_dialog_content = "Aku akan memberitahumu semua yang aku tahu kalau saja kamu bisa menghentikan preman-preman itu untuk menginjakkan kaki di sini lagi!",
  str_homestory_N23dianying_90030301_71_dialog_content = "Surat geng rahasia?",
  str_homestory_N23dianying_90030301_71X1_dialog_content = "Surat geng rahasia?",
  str_homestory_N23dianying_90030301_71X2_dialog_content = "Betul sekali. Jika Anda mengejar mereka sekarang, orang-orang yang memberi saya surat itu tidak mungkin pergi jauh.",
  str_homestory_N23dianying_90030301_72_dialog_content = "Anda benar-benar telah banyak membantu. Terima kasih atas kerja sama Anda, bartender.",
  str_homestory_N23dianying_90030301_73_dialog_content = "Setelah saya tahu apa yang terjadi, saya akan bertanggung jawab untuk menjaga tempat ini tetap aman.",
  str_homestory_N23dianying_90030301_74_dialog_content = "Nah, lanjutkan!",
  str_homestory_N23dianying_90030301_74X1_dialog_content = "Saya perlu melihat apa yang dikatakannya sebelum saya dapat menilai kebenaran informasi Anda.",
  str_homestory_N23dianying_90030301_74X2_dialog_content = "Lagi pula, saya tidak mengerti mengapa mereka mempercayakan barang penting seperti itu kepada Anda.",
  str_homestory_N23dianying_90030301_74X3_dialog_content = "Baiklah, lanjutkan saja.",
  str_homestory_N23dianying_90030301_75_dialog_content = "\"Gadis Bulanku tersayang,\"",
  str_homestory_N23dianying_90030301_76_dialog_content = "\"Saya menghargai antusiasme tulus Anda dan mengagumi keterusterangan Anda yang berani.\"",
  str_homestory_N23dianying_90030301_77_dialog_content = "\"Tapi, kebanyakan minta maaf, aku tidak merasakan hal yang sama\"...",
  str_homestory_N23dianying_90030301_78_dialog_content = "Ini surat cinta, Chubb!",
  str_homestory_N23dianying_90030301_79_dialog_content = "Apa yang kamu lakukan?",
  str_homestory_N23dianying_90030301_80_dialog_content = "Apakah ini... surat untukku?",
  str_homestory_N23dianying_90030301_81_dialog_content = "Eh, ini, ini...",
  str_homestory_N23dianying_90030301_82_dialog_content = "Nama saya adalah \"Beauty Under the Moon\"...",
  str_homestory_N23dianying_90030301_83_dialog_content = "Ini ditujukan kepada saya, benar?",
  str_homestory_N23dianying_90030301_84_dialog_content = "Y-Ya.",
  str_homestory_N23dianying_90030301_85_dialog_content = "Saya jelas baru saja mendengar, bahwa dia tidak dapat membalas perasaan saya ...",
  str_homestory_N23dianying_90030301_86_dialog_content = "Pada akhirnya, saya masih tidak bisa mewujudkannya.",
  str_homestory_N23dianying_90030301_87_dialog_content = "Hai! Mengapa Anda menyentuh pemutar rekaman kami?!",
  str_homestory_N23dianying_90030301_87X1_dialog_content = "Pffffft—",
  str_homestory_N23dianying_90030301_87X2_dialog_content = "Ha ha ha!",
  str_homestory_N23dianying_90030301_87X3_dialog_content = "Charon, tenang! Chubb.",
  str_homestory_N23dianying_90030301_88_dialog_content = "Saya bertemu dengannya sebulan yang lalu, di bawah bulan purnama.",
  str_homestory_N23dianying_90030301_89_dialog_content = "Saya bersembunyi dari beberapa preman pada saat itu, dan dia menyelamatkan saya.",
  str_homestory_N23dianying_90030301_90_dialog_content = "Er... Kenapa dia memberitahu kita ini?",
  str_homestory_N23dianying_90030301_91_dialog_content = "Saya bertanya-tanya di mana-mana di kota, sebelum akhirnya saya tahu siapa dia.",
  str_homestory_N23dianying_90030301_92_dialog_content = "Tapi saya tertipu jika saya berpikir bahwa seorang pria bertubuh tinggi bisa jatuh cinta pada seseorang seperti saya.",
  str_homestory_N23dianying_90030301_93_dialog_content = "Apakah itu sebabnya Anda memilih untuk menggunakan nama pena, dan menulis surat untuknya?",
  str_homestory_N23dianying_90030301_93X1_dialog_content = "Apakah itu sebabnya Anda memilih untuk menggunakan nama pena, dan menulis surat untuknya?",
  str_homestory_N23dianying_90030301_94_dialog_content = "Ya... Karena saya pikir, apapun yang terjadi, saya tidak akan membiarkan diri saya menyesal.",
  str_homestory_N23dianying_90030301_95_dialog_content = "Tetapi saya telah belajar bahwa beberapa jurang terlalu lebar untuk dilewati dengan keberanian saja.",
  str_homestory_N23dianying_90030301_95X1_dialog_content = "Sangat mengagumkan bagi seorang wanita untuk memiliki keberanian seperti itu.",
  str_homestory_N23dianying_90030301_95X2_dialog_content = "Ini adalah kerugiannya untuk menolak wanita yang begitu elegan.",
  str_homestory_N23dianying_90030301_96_dialog_content = "Aku pasti bisa mengerti bagaimana perasaanmu, Moon Maiden.",
  str_homestory_N23dianying_90030301_97_dialog_content = "Apakah simpati itu merayap masuk?!",
  str_homestory_N23dianying_90030301_98_dialog_content = "Fakta bahwa Anda memiliki keberanian untuk melakukan itu sejak awal sangat mengagumkan.",
  str_homestory_N23dianying_90030301_99_dialog_content = "Saya pikir Anda tidak harus menyerah pada hati Anda begitu cepat. Bantu dia memahami Anda.",
  str_homestory_N23dianying_90030301_100_dialog_content = "Jangan menyerah begitu saja pada rintangan pertama.",
  str_homestory_N23dianying_90030301_101_dialog_content = "Terima kasih... Kau orang pertama yang mengatakan itu padaku.",
  str_homestory_N23dianying_90030301_101X1_dialog_content = "Saya Sheriff di sekitar sini, jadi jika Anda membutuhkan sesuatu di masa depan, pastikan untuk datang dan menemukan saya.",
  str_homestory_N23dianying_90030301_101X2_dialog_content = "Dan... Aku minta maaf karena membaca suratmu. Aku seharusnya tidak melakukan itu.",
  str_homestory_N23dianying_90030301_101X3_dialog_content = "Saya percaya Anda hanya memiliki niat baik.",
  str_homestory_N23dianying_90030301_101X4_dialog_content = "Terima kasih atas kebaikan dan pengertian Anda.",
  str_homestory_N23dianying_90030301_101X5_dialog_content = "Nah, untuk Anda, Tn. Charon.",
  str_homestory_N23dianying_90030301_101X6_dialog_content = "Eh... Ya?",
  str_homestory_N23dianying_90030301_101X7_dialog_content = "Bukankah seharusnya saya menjadi Tuan Bartender?",
  str_homestory_N23dianying_90030301_101X8_dialog_content = "Tidak mungkin aku bisa memaafkanmu, karena mencampuri urusan paling pribadi seorang wanita muda.",
  str_homestory_N23dianying_90030301_101X9_dialog_content = "Perilaku tercela seperti itu harus dihukum oleh hukum dan dikutuk oleh moralitas umum!",
  str_homestory_N23dianying_90030301_101X10_dialog_content = "…!",
  str_homestory_N23dianying_90030301_101X11_dialog_content = "Kecilkan, Pittman!",
  str_homestory_N23dianying_90030301_101X12_dialog_content = "Dia menjadi sedikit terlalu ke dalam karakter, Chubb!",
  str_homestory_N23dianying_90030301_101X13_dialog_content = "Tunggu, tunggu, tunggu!",
  str_homestory_N23dianying_90030301_101X14_dialog_content = "Bukankah kita sedang syuting? Apa yang dikatakan skrip?",
  str_homestory_N23dianying_90030301_101X15_dialog_content = "Bukannya aku ingin membaca!",
  str_homestory_N23dianying_90030301_101X16_dialog_content = "Hmph, masih mengerang.",
  str_homestory_N23dianying_90030301_101X17_dialog_content = "Ambil hukumanmu!",
  str_homestory_N23dianying_90030301_101X18_dialog_content = "Tunggu!",
  str_homestory_N23dianying_90030301_101X19_dialog_content = "Jangan merusak set saya, ATAU alat peraga!",
  str_homestory_N23dianying_90030301_102_dialog_content = "Saya Sheriff di sekitar sini, jadi jika Anda membutuhkan sesuatu di masa depan, pastikan untuk datang dan menemukan saya.",
  str_homestory_N23dianying_90030301_103_dialog_content = "Bagaimanapun, saya masih memiliki hal-hal yang harus dilakukan, jadi saya harus pergi. Sampai jumpa.",
  str_homestory_N23dianying_90030301_104_dialog_content = "Tunggu sebentar! Bagaimana dengan pertarungannya?",
  str_homestory_N23dianying_90030301_105_dialog_content = "Berdasarkan apa yang baru saja saya lihat, saya tidak puas bahwa Anda dapat memberikan intelijen yang dapat diandalkan.",
  str_homestory_N23dianying_90030301_106_dialog_content = "Sangat tercela untuk mencampuri urusan paling pribadi seorang wanita.",
  str_homestory_N23dianying_90030301_107_dialog_content = "Saya akan menilai dan menilai sendiri. Selamat tinggal.",
  str_homestory_N23dianying_90030301_108_dialog_content = "Bagaimana ini mungkin...",
  str_homestory_N23dianying_90030301_109_dialog_content = "Pria itu barusan, apakah dia... benar-benar Sheriff?",
  str_homestory_N23dianying_90030301_110_option_content = "Minta maaf dengan tulus",
  str_homestory_N23dianying_90030301_110X1_dialog_content = "Jangan hanya berdiri di sana, petugas! Sampaikan permintaan maafmu!",
  str_homestory_N23dianying_90030301_111_dialog_content = "Ya.",
  str_homestory_N23dianying_90030301_112_dialog_content = "Saya minta maaf karena membuka surat pribadi yang begitu penting tanpa izin.",
  str_homestory_N23dianying_90030301_113_dialog_content = "Tidak masalah. Bagaimanapun, itu adalah panggilan penilaian yang dibuat pada saat kritis untuk kepentingan organisasi.",
  str_homestory_N23dianying_90030301_114_dialog_content = "Organisasi?",
  str_homestory_N23dianying_90030301_115_dialog_content = "Surat itu ditulis dengan kode. Ternyata hanya surat cinta.",
  str_homestory_N23dianying_90030301_116_dialog_content = "Meskipun ada risiko yang melekat dalam membukanya di depan Sheriff... Tampaknya kami lolos begitu saja, karena dia tidak curiga sedikit pun.",
  str_homestory_N23dianying_90030301_117_dialog_content = "Dan Night Impression memenuhi reputasinya sebagai tempat yang dapat dipercaya.",
  str_homestory_N23dianying_90030301_118_dialog_content = "Tunggu, maksudmu kau benar-benar bagian dari geng?",
  str_homestory_N23dianying_90030301_119_dialog_content = "Semua itu hanya dibuat-buat di tempat?",
  str_homestory_N23dianying_90030301_120_dialog_content = "Yap.",
  str_homestory_N23dianying_90030301_121_dialog_content = "Wow! Saya tidak melihat itu datang, Chubb!",
  str_homestory_N23dianying_90030301_122_dialog_content = "Omong-omong... Sekarang setelah aku mengambil surat itu dengan aman, aku harus pergi ke perhentian berikutnya dalam misi ini.",
  str_homestory_N23dianying_90030301_123_dialog_content = "Sampai jumpa, Tuan Bartender.",
  str_homestory_N23dianying_90030301_124_dialog_content = "...",
  str_homestory_N23dianying_90030301_125_dialog_content = "Apa yang baru saja terjadi?!",
  str_homestory_N23dianying_90030301_126_option_content = "Sarankan dia untuk menyerah",
  str_homestory_N23dianying_90030301_126X1_dialog_content = "Ayo, petugas, tunggu apa lagi? Ini adalah bagian di mana Anda dimaksudkan untuk mencoba membujuknya agar tidak mengejar hubungan!",
  str_homestory_N23dianying_90030301_127_dialog_content = "Oke.",
  str_homestory_N23dianying_90030301_128_dialog_content = "Itu benar, Moon Maiden... Ada sesuatu yang harus kukatakan padamu.",
  str_homestory_N23dianying_90030301_129_dialog_content = "Kebetulan pria yang Anda kagumi adalah sosok berbahaya di geng!",
  str_homestory_N23dianying_90030301_130_dialog_content = "…!",
  str_homestory_N23dianying_90030301_131_dialog_content = "Sheriff barusan tidak percaya padaku, itulah sebabnya dia mendorongmu untuk mengejarnya.",
  str_homestory_N23dianying_90030301_132_dialog_content = "Tapi saya tetap menyarankan Anda untuk pergi begitu saja. Bagaimana jika dia tidak benar-benar pria baik hati yang Anda pikirkan?",
  str_homestory_N23dianying_90030301_133_dialog_content = "... Jadi Anda ingin mengungkapkan identitas aslinya kepada Sheriff?",
  str_homestory_N23dianying_90030301_134_dialog_content = "Ya. Bahkan jika Sheriff tidak mempercayaiku, aku tidak akan berhenti mengikuti petunjuknya.",
  str_homestory_N23dianying_90030301_135_dialog_content = "...",
  str_homestory_N23dianying_90030301_136_dialog_content = "Gadis Bulan?",
  str_homestory_N23dianying_90030301_137_dialog_content = "A-Apa yang akan kamu lakukan?!",
  str_homestory_N23dianying_90030301_138_dialog_content = "Saya pikir pada awalnya bahwa Sheriff memaksa Anda untuk membaca surat itu.",
  str_homestory_N23dianying_90030301_139_dialog_content = "Apakah pria itu melakukan kesalahan...?",
  str_homestory_N23dianying_90030301_140_dialog_content = "A-Apa maksudmu?",
  str_homestory_N23dianying_90030301_141_dialog_content = "Surat itu ditulis dengan kode. Ternyata hanya surat cinta.",
  str_homestory_N23dianying_90030301_142_dialog_content = "Untuk mencegah krisis seperti itu.",
  str_homestory_N23dianying_90030301_143_dialog_content = "Dan kebetulan saya adalah salah satu pemain dalam misi klandestin ini.",
  str_homestory_N23dianying_90030301_144_dialog_content = "Wow! Saya tidak melihat itu datang, Chubb!",
  str_homestory_N23dianying_90030301_145_dialog_content = "Tunggu sebentar! Jadi kamu sebenarnya bagian dari geng?!",
  str_homestory_N23dianying_90030301_146_dialog_content = "Ya... Aku minta maaf atas dalihnya.",
  str_homestory_N23dianying_90030301_147_dialog_content = "Tetapi keamanan organisasi adalah yang terpenting. Jadi tolong, Tuan Bartender...",
  str_homestory_N23dianying_90030301_148_dialog_content = "Kau harus tutup mulut... selamanya.",
  str_homestory_N23dianying_90030301_149_dialog_content = "A-Apa yang kamu lakukan?",
  str_homestory_N23dianying_90030301_150_dialog_content = "Jangan mendekat!",
  str_homestory_N23dianying_90030301_151_option_content = "Identitas pertanyaan",
  str_homestory_N23dianying_90030301_151X1_dialog_content = "Mengacak-acak garis Anda? Anda mempertanyakan identitasnya, petugas!",
  str_homestory_N23dianying_90030301_152_dialog_content = "Kedengarannya benar.",
  str_homestory_N23dianying_90030301_153_dialog_content = "Jadi, Gadis Bulan?",
  str_homestory_N23dianying_90030301_154_dialog_content = "Ya?",
  str_homestory_N23dianying_90030301_155_dialog_content = "Apakah Anda benar-benar hanya pelamar yang ditolak?",
  str_homestory_N23dianying_90030301_156_dialog_content = "...",
  str_homestory_N23dianying_90030301_157_dialog_content = "Tidak baik mengetahui terlalu banyak, Tn. Bartender.",
  str_homestory_N23dianying_90030301_158_dialog_content = "Tapi aku akan pergi, mengingat aku memiliki surat itu.",
  str_homestory_N23dianying_90030301_159_dialog_content = "Aku tahu ada sesuatu yang berbau amis.",
  str_homestory_N23dianying_90030301_160_dialog_content = "Saya yakin ada lebih dari sekadar memenuhi mata dalam surat itu. Lebih baik aku mencatat apa yang dikatakannya, selagi aku masih ingat.",
  str_homestory_N23dianying_90030301_161_dialog_content = "Sekarang, di mana pena dan kertas...",
  str_homestory_N23dianying_90030301_162_dialog_content = "Anda tidak bisa membiarkannya begitu saja, bukan?",
  str_homestory_N23dianying_90030301_163_dialog_content = "K-Kamu masih—",
  str_homestory_N23dianying_90030301_164_dialog_content = "Chu! Peleraian! Chubb!",
  str_homestory_N23dianying_90030301_165_dialog_content = "Protagonis film tidak pernah memeriksa ruangan, Chubb!",
  str_homestory_N23dianying_90030301_166_dialog_content = "Mengapa pria itu mempercayakan barang penting seperti itu kepada Anda?",
  str_homestory_N23dianying_90030301_167_dialog_content = "Kecuali itu semua adalah bagian dari rencana?",
  str_homestory_N23dianying_90030301_168_dialog_content = "Apapun, untuk mencegah gangguan tak terduga dari timbul. Mengapa kita tidak berjalan-jalan bersama, Tn. Bartender?",
  str_homestory_N23dianying_90030301_169_dialog_content = "Tunggu! Apa yang sedang kamu lakukan?!",
  str_homestory_N23dianying_90030301_170_dialog_content = "Jangan mendekat!",
  str_homestory_N23dianying_90030301_171_dialog_content = "Jangan mengambil hal-hal terlalu jauh, Anda sepasang bergumam ...",
  str_homestory_N23dianying_90030301_172_dialog_content = "Tenang, Tuan Bartender. Kami tidak bermaksud menyusahkan Anda.",
  str_homestory_N23dianying_90030301_172X1_dialog_content = "Saya berteman baik dengan bos Anda. Dia tidak akan mengatakan apa-apa jika saya mengambil sedikit ruang di sini.",
  str_homestory_N23dianying_90030301_173_dialog_content = "Kami juga berteman baik dengan bos. Saya yakin dia tidak akan keberatan",
  str_homestory_N23dianying_90030301_174_dialog_content = "Er... B-Bos?",
  str_homestory_N23dianying_90030301_175_dialog_content = "... Baik. Saya mendapatkannya.",
  str_homestory_N23dianying_90030301_176_dialog_content = "Drat. Menggunakan bos saya sendiri untuk mengancam saya.",
  str_homestory_N23dianying_90030301_177_dialog_content = "Tempat ini tidak akan menjadi apa-apa selain tempat nongkrong geng pada tingkat ini.",
  str_homestory_N23dianying_90030301_178_dialog_content = "Maaf, ini bukan yang kita sepakati. Tidak mungkin aku bisa menerima.",
  str_homestory_N23dianying_90030301_179_dialog_content = "Setelah bertahun-tahun berteman, tidak bisakah kamu mengalah sedikit saja?",
  str_homestory_N23dianying_90030301_179X1_dialog_content = "Anda sudah seperti saudara bagi saya selama bertahun-tahun. Tidak bisakah Anda menemukan sedikit ruang gerak?",
  str_homestory_N23dianying_90030301_180_dialog_content = "Ini hanya bisnis. Bagaimanapun, semuanya adil dalam cinta dan pusat perbelanjaan. Mereka adalah medan perang, bukan tempat untuk berteman.",
  str_homestory_N23dianying_90030301_181_dialog_content = "Jika Anda berada di posisi saya, Anda akan melakukan hal yang sama.",
  str_homestory_N23dianying_90030301_182_dialog_content = "Dan Anda tidak benar-benar menganggap saya sebagai teman sejati, dilihat dari cara Anda merusak kontrak terakhir kali.",
  str_homestory_N23dianying_90030301_183_dialog_content = "Ah, itu hanya kesalahpahaman kecil.",
  str_homestory_N23dianying_90030301_184_dialog_content = "Oh? Apakah terakhir kali Anda ikut campur dalam bisnis kami juga merupakan kesalahpahaman?",
  str_homestory_N23dianying_90030301_185_dialog_content = "Tentang itu...",
  str_homestory_N23dianying_90030301_186_dialog_content = "Atau waktu sebelum itu, ketika Anda berlari di aroma Sheriff?",
  str_homestory_N23dianying_90030301_187_dialog_content = "Beberapa orang yang tersisa untuk kami melakukan yang terbaik untuk melindungi barang dagangan bos, tetapi kami membayar harga yang sangat tinggi.",
  str_homestory_N23dianying_90030301_188_dialog_content = "...",
  str_homestory_N23dianying_90030301_189_dialog_content = "Saya benar-benar tidak dapat memahami mengapa orang-orang di atas sana masih mau bekerja dengan Anda.",
  str_homestory_N23dianying_90030301_190_dialog_content = "Tapi aku... Aku sudah menunggu untuk menunjukkan betapa marahnya kamu padaku.",
  str_homestory_N23dianying_90030301_191_dialog_content = "Dan kamu BERANI menggunakan kata 'teman' denganku?!",
  str_homestory_N23dianying_90030301_192_dialog_content = "Sekarang, sekarang—jika Anda akan bertarung, bawa ke tempat lain.",
  str_homestory_N23dianying_90030301_193_dialog_content = "Begitukah cara negosiasi bekerja?!",
  str_homestory_N23dianying_90030301_194_dialog_content = "Berhenti dengan pretensi. Semua orang keluar untuk diri mereka sendiri. Tidak ada benar atau salah di sini.",
  str_homestory_N23dianying_90030301_195_dialog_content = "Bukankah kamu diam-diam memberi informasi tentang kami ke Lionhead Gang di masa lalu?",
  str_homestory_N23dianying_90030301_196_dialog_content = "Kami hanya membalas budi. Menyeimbangkan timbangan.",
  str_homestory_N23dianying_90030301_197_dialog_content = "Sepertinya Anda menyimpan banyak dendam terhadap kami.",
  str_homestory_N23dianying_90030301_198_dialog_content = "Jadi mari kita selesaikan semua skor hari ini, di sini dan sekarang juga.",
  str_homestory_N23dianying_90030301_199_dialog_content = "Baik oleh saya jika Anda cukup berani untuk mengakui kesalahan Anda.",
  str_homestory_N23dianying_90030301_200_dialog_content = "Jangan bertengkar di sini, kalian berdua!",
  str_homestory_N23dianying_90030301_201_dialog_content = "Semua orang berhenti! Letakkan senjatamu!",
  str_homestory_N23dianying_90030301_202_dialog_content = "Saya baru saja selesai merapikan tempat ini!",
  str_homestory_N23dianying_90030301_202X1_dialog_content = "Saya selalu mengatakan bahwa itu adalah kesalahpahaman.",
  str_homestory_N23dianying_90030301_202X2_dialog_content = "Kami tidak bisa menulis dengan cara yang kaku seperti Anda.",
  str_homestory_N23dianying_90030301_202X3_dialog_content = "Oh? Jadi terakhir kali, ketika Anda merampok barang dagangan kami, itu juga salah paham?",
  str_homestory_N23dianying_90030301_202X4_dialog_content = "Hmm…",
  str_homestory_N23dianying_90030301_202X5_dialog_content = "Shadowlord menyuruhku mengejarmu melintasi Gurun Rediesel selama tiga hari tiga malam penuh.",
  str_homestory_N23dianying_90030301_202X6_dialog_content = "Anda hanya berputar-putar, membuat segalanya berantakan sebelum melemparkan semuanya kembali kepada saya.",
  str_homestory_N23dianying_90030301_202X7_dialog_content = "Itu salah paham juga, kan?",
  str_homestory_N23dianying_90030301_202X8_dialog_content = "Hei, bukankah kita sedang membuat film?",
  str_homestory_N23dianying_90030301_202X9_dialog_content = "Anda memilih sekarang untuk mengemukakan semua ini?",
  str_homestory_N23dianying_90030301_202X10_dialog_content = "Taki, Sinsa, tolong tenang!",
  str_homestory_N23dianying_90030301_202A1_dialog_content = "Mereka sudah mulai berkelahi!",
  str_homestory_N23dianying_90030301_202X11_dialog_content = "Maaf, tapi kurasa kita tidak bisa melanjutkan syuting.",
  str_homestory_N23dianying_90030301_202X12_dialog_content = "Aku hampir tidak bisa menahan amarahku sejak pertama kali melihat wajahmu di lokasi syuting.",
  str_homestory_N23dianying_90030301_202X13_dialog_content = "Memukau. Jadi apa yang akan Anda lakukan? Mau tango?",
  str_homestory_N23dianying_90030301_202X14_dialog_content = "Ayo.",
  str_homestory_N23dianying_90030301_202X15_dialog_content = "GET OUT jika Anda akan melawan! Jangan hancurkan set atau propertinya!",
  str_homestory_N23dianying_90030401_1_dialog_content = "Apakah Anda merasa tidak sehat, Yang Mulia?",
  str_homestory_N23dianying_90030401_2_dialog_content = "Novio mengatakan bahwa kamu belum makan dengan baik akhir-akhir ini.",
  str_homestory_N23dianying_90030401_3_dialog_content = "Mereka khawatir, dan telah berusaha mencari resep baru untuk Anda.",
  str_homestory_N23dianying_90030401_4_dialog_content = "Maaf membuatmu khawatir, Lola.",
  str_homestory_N23dianying_90030401_5_dialog_content = "Aku hanya tidak punya banyak nafsu makan akhir-akhir ini. Tidak perlu khawatir.",
  str_homestory_N23dianying_90030401_6_dialog_content = "Mengapa tidak mencoba madu yang baru saja saya kumpulkan? Ini benar-benar manis!",
  str_homestory_N23dianying_90030401_S6_dialog_content = "Atau, jika Anda tidak ingin madu, kami memiliki beberapa hidangan baru.",
  str_homestory_N23dianying_90030401_7_dialog_content = "Madu baik-baik saja, tetapi gula sebenarnya tidak baik untuk tubuh.",
  str_homestory_N23dianying_90030401_8_dialog_content = "Hah? Kamu siapa?",
  str_homestory_N23dianying_90030401_X8_dialog_content = "Gadis kecil, terlalu banyak makanan penutup akan membuatmu gemuk.",
  str_homestory_N23dianying_90030401_S8_dialog_content = "Yang Mulia.",
  str_homestory_N23dianying_90030401_S9_dialog_content = "Saya Chef Eve, dipekerjakan oleh Pak Novio untuk membuat hidangan baru untuk Anda.",
  str_homestory_N23dianying_90030401_9_dialog_content = "Saya minta maaf, Yang Mulia.",
  str_homestory_N23dianying_90030401_10_dialog_content = "Saya Chef Fleur, dipekerjakan oleh Mr Novio untuk membuat hidangan baru untuk Anda.",
  str_homestory_N23dianying_90030401_11_dialog_content = "Saya berasal dari Gurun Rediesel, jauh dari Northland.",
  str_homestory_N23dianying_90030401_12_dialog_content = "Saya percaya bahwa saya akan dapat membawakan Anda hidangan yang belum pernah Anda rasakan sebelumnya.",
  str_homestory_N23dianying_90030401_13_dialog_content = "Lihat Minuman Rediesel ini? Ini tidak seperti minuman apa pun yang Anda miliki di sini.",
  str_homestory_N23dianying_90030401_14_dialog_content = "Saya yakin rasanya yang unik dan lembut akan menggugah selera Anda.",
  str_homestory_N23dianying_90030401_X14_dialog_content = "Saya koki baru yang dipekerjakan oleh pria Novio yang lucu itu.",
  str_homestory_N23dianying_90030401_X15_dialog_content = "Saya dari Gurun Rediesel dan membawa hidangan yang belum pernah Anda dengar bersama saya.",
  str_homestory_N23dianying_90030401_X16_dialog_content = "Ini adalah Istana Musim Dingin. Kami memiliki setiap hidangan dari setiap sudut benua!",
  str_homestory_N23dianying_90030401_X17_dialog_content = "Aku ragu itu masalahnya, Gadis Kecil.",
  str_homestory_N23dianying_90030401_X18_dialog_content = "Lihat Minuman Rediesel ini? Ini tidak seperti minuman apa pun yang Anda miliki di sini.",
  str_homestory_N23dianying_90030401_X19_dialog_content = "Ini adalah resep eksklusif untuk Gurun Rediesel, dan itu diturunkan dan tidak ditemukan dalam catatan apa pun.",
  str_homestory_N23dianying_90030401_S14_dialog_content = "Tidak hanya itu, itu jauh lebih merangsang daripada minuman lain juga.",
  str_homestory_N23dianying_90030401_S15_dialog_content = "Terakhir kali, PlayerName hanya memiliki beberapa tegukan dengan saudara saya dan...",
  str_homestory_N23dianying_90030401_S16_dialog_content = "T-Tunggu! Itu tidak ada dalam naskah, Eve!",
  str_homestory_N23dianying_90030401_S17_dialog_content = "Oh, benar! Jadi apa garis saya?",
  str_homestory_N23dianying_90030401_S18_dialog_content = "Oh, dan Naga Berkaki Empat Emas ini.",
  str_homestory_N23dianying_90030401_15_dialog_content = "Pastinya memiliki aroma yang khas.",
  str_homestory_N23dianying_90030401_16_dialog_content = "Kamu benar! Aku sudah bisa mencium baunya dari jauh-jauh sini!",
  str_homestory_N23dianying_90030401_X20_dialog_content = "Naga Berkaki Empat Emas ini.",
  str_homestory_N23dianying_90030401_17_dialog_content = "Dan Naga Berkaki Empat Emas ini.",
  str_homestory_N23dianying_90030401_18_dialog_content = "Itu terbuat dari kadal gurun dari bagian terdalam gurun. Dagingnya keras dengan kulit yang renyah.",
  str_homestory_N23dianying_90030401_19_dialog_content = "Ini adalah salah satu makanan paling terkenal dari Gurun Rediesel.",
  str_homestory_N23dianying_90030401_20_dialog_content = "Kedengarannya bagus.",
  str_homestory_N23dianying_90030401_21_dialog_content = "Uhm... T-Itu berbeda.",
  str_homestory_N23dianying_90030401_22_dialog_content = "Adapun Desert Jewel, itu adalah hidangan khas yang sebenarnya.",
  str_homestory_N23dianying_90030401_23_dialog_content = "Itu terbuat dari organ internal cacing pasir, makhluk unik di Gurun Rediesel.",
  str_homestory_N23dianying_90030401_24_dialog_content = "I-Organ dalam dari cacing pasir!?",
  str_homestory_N23dianying_90030401_25_dialog_content = "Betul sekali. Mereka dibumbui dengan rediesel, dan bumbu khas kami, kemudian dipanggang hingga kulitnya sedikit gosong.",
  str_homestory_N23dianying_90030401_26_dialog_content = "Ini aromatik, berair, dan bergizi tinggi—",
  str_homestory_N23dianying_90030401_27_dialog_content = "Berhenti, berhenti, berhenti! Cukup!",
  str_homestory_N23dianying_90030401_28_dialog_content = "Anda orang-orang Rediesel Wrench benar-benar makan hal-hal aneh!",
  str_homestory_N23dianying_90030401_29_dialog_content = "Bagaimana perut Anda bisa menerimanya?",
  str_homestory_N23dianying_90030401_30_dialog_content = "Diam, Lala. Kami sedang melakukan iklan baca di sini!",
  str_homestory_N23dianying_90030401_31_dialog_content = "M-Maaf...",
  str_homestory_N23dianying_90030401_32_dialog_content = "Itu pasti terdengar menarik. Anda harus menunjukkan kami piring.",
  str_homestory_N23dianying_90030401_X32_dialog_content = "Itu pasti terdengar menarik. Anda harus menunjukkan kami piring.",
  str_homestory_N23dianying_90030401_33_dialog_content = "Dengan senang hati, Yang Mulia.",
  str_homestory_N23dianying_90030401_X33_dialog_content = "Rediesel gourmet, rasa yang bahkan membuat penasaran Ratu Utara.",
  str_homestory_N23dianying_90030401_X34_dialog_content = "Festival Makanan Rediesel sekarang tersedia di Gurun Rediesel! Hanya empat kali setahun!",
  str_homestory_N23dianying_90030401_X35_dialog_content = "Anda bahkan mungkin bertemu saya di sana jika Anda beruntung.",
  str_homestory_N23dianying_90030401_S33_dialog_content = "Itu pasti terdengar menarik. Anda harus menunjukkan kami piring.",
  str_homestory_N23dianying_90030401_S34_dialog_content = "Dengan senang hati, Yang Mulia!",
  str_homestory_N23dianying_90030401_34_dialog_content = "Rediesel gourmet, rasa yang bahkan menyemangati Ratu Utara.",
  str_homestory_N23dianying_90030401_35_dialog_content = "Festival Makanan Rediesel sekarang tersedia di Gurun Rediesel! Hanya empat kali setahun!",
  str_homestory_N23dianying_90030401_36_dialog_content = "Tertarik? Hubungi Odd Jobs, kolaborator kami di Umbraton!",
  str_homestory_N23dianying_90030401_37_dialog_content = "Diskon grup hebat dan penawaran hebat lainnya untuk 100 penanya pertama!",
  str_homestory_N23dianying_90030401_38_dialog_content = "Jangan lewatkan!",
  str_homestory_N23dianying_90030501_1_dialog_content = "Apakah Anda baik-baik saja, Nona Wakil?",
  str_homestory_N23dianying_90030501_2_dialog_content = "Oh maafkan saya. Aku blanked out sejenak di sana.",
  str_homestory_N23dianying_90030501_3_dialog_content = "Apa yang Anda katakan?",
  str_homestory_N23dianying_90030501_X1_dialog_content = "Direktur? Apakah kamu baik-baik saja?",
  str_homestory_N23dianying_90030501_X2_dialog_content = "Maaf! Aku terdiam sejenak di sana.",
  str_homestory_N23dianying_90030501_X3_dialog_content = "Apa katamu?",
  str_homestory_N23dianying_90030501_S1_dialog_content = "Pak Minos? Apakah kamu baik-baik saja?",
  str_homestory_N23dianying_90030501_S2_dialog_content = "Oh maafkan saya.",
  str_homestory_N23dianying_90030501_S3_dialog_content = "Bisakah Anda mengulangi pertanyaannya lagi?",
  str_homestory_N23dianying_90030501_S4_dialog_content = "Tidak masalah. Anda terlihat kelelahan...",
  str_homestory_N23dianying_90030501_S5_dialog_content = "Yang ingin saya tanyakan adalah... Terakhir kali, Anda mengatakan bahwa Anda menyesal membuat film ini.",
  str_homestory_N23dianying_90030501_4_dialog_content = "Tentu. Yang ingin saya tanyakan adalah...",
  str_homestory_N23dianying_90030501_5_dialog_content = "Terakhir kali, Anda mengatakan Anda menyesal membuat film ini.",
  str_homestory_N23dianying_90030501_6_dialog_content = "Mengapa demikian?",
  str_homestory_N23dianying_90030501_X4_dialog_content = "I-Itu karena kami menyadari sampai dirilis bahwa...",
  str_homestory_N23dianying_90030501_X5_dialog_content = "Film ini mungkin terkutuk.",
  str_homestory_N23dianying_90030501_S6_dialog_content = "Meskipun saya tidak menganjurkan takhayul semacam ini, secara pribadi ...",
  str_homestory_N23dianying_90030501_S7_dialog_content = "Tapi kru, mereka semua mengatakan film ini terkutuk.",
  str_homestory_N23dianying_90030501_7_dialog_content = "Karena ... tidak sampai dirilis kami menyadari ...",
  str_homestory_N23dianying_90030501_8_dialog_content = "Film ini mungkin terkutuk.",
  str_homestory_N23dianying_90030501_9_dialog_content = "Dikutuk?",
  str_homestory_N23dianying_90030501_10_dialog_content = "Ya. Setiap orang yang telah melihat film atau berpartisipasi dalam pembuatannya...",
  str_homestory_N23dianying_90030501_11_dialog_content = "Semua mengalami hal-hal yang \"aneh\".",
  str_homestory_N23dianying_90030501_12_dialog_content = "Halo semuanya. Hari ini, saya di sini untuk membawa Anda ke dalam Rumah Hantu Andersen!",
  str_homestory_N23dianying_90030501_13_dialog_content = "Itu awalnya dimiliki oleh Lady Astor.",
  str_homestory_N23dianying_90030501_14_dialog_content = "Dia akan berteriak ketika lilin padam.",
  str_homestory_N23dianying_90030501_15_dialog_content = "Akhirnya, dia tewas dalam kebakaran.",
  str_homestory_N23dianying_90030501_16_dialog_content = "Gaya mantan pemilik itu... benar-benar unik.",
  str_homestory_N23dianying_90030501_17_dialog_content = "Hanya boneka-boneka ini. Mereka agak aneh untuk dilihat.",
  str_homestory_N23dianying_90030501_18_dialog_content = "<color=#e8d9bb>*Bunyi kotak musik penutup*</color>",
  str_homestory_N23dianying_90030501_19_dialog_content = "\"Satu boneka kecil, dua boneka kecil, tiga boneka kecil♪\"",
  str_homestory_N23dianying_90030501_20_dialog_content = "A-Ahhhh!!!! Itu kembali!",
  str_homestory_N23dianying_90030501_X20_dialog_content = "Saya telah mendengar wanita itu menyanyikan lagu ini setiap malam sejak hari itu!",
  str_homestory_N23dianying_90030501_X21_dialog_content = "Dan saya perhatikan suaranya sepertinya semakin dekat dengan saya!",
  str_homestory_N23dianying_90030501_X22_dialog_content = "Rekan-rekan aktor saya telah mengatakan hal yang sama kepada saya.",
  str_homestory_N23dianying_90030501_S20_dialog_content = "Beberapa aktor dan staf telah mendengarnya bernyanyi setiap malam sejak itu.",
  str_homestory_N23dianying_90030501_S21_dialog_content = "Tapi saya pribadi tidak mendengar apa-apa.",
  str_homestory_N23dianying_90030501_S22_dialog_content = "Mungkinkah mereka terlalu lelah atau berhalusinasi?",
  str_homestory_N23dianying_90030501_21_dialog_content = "Saya telah mendengar wanita itu menyanyikan lagu ini setiap malam sejak hari itu!",
  str_homestory_N23dianying_90030501_22_dialog_content = "Dan saya perhatikan suaranya sepertinya semakin dekat dengan saya!",
  str_homestory_N23dianying_90030501_23_dialog_content = "Mungkinkah Anda terlalu lelah atau berhalusinasi?",
  str_homestory_N23dianying_90030501_24_dialog_content = "Saya juga menonton film sebelum wawancara ini.",
  str_homestory_N23dianying_90030501_25_dialog_content = "Tidak ada yang terjadi padaku.",
  str_homestory_N23dianying_90030501_26_dialog_content = "Mungkinkah hanya kebetulan...?",
  str_homestory_N23dianying_90030501_27_dialog_content = "<color=#e8d9bb>*langkah kaki mendekat*</color>",
  str_homestory_N23dianying_90030501_X27_dialog_content = "Suara apa itu?",
  str_homestory_N23dianying_90030501_S27_dialog_content = "A-Suara apa itu?",
  str_homestory_N23dianying_90030501_S28_dialog_content = "Angin pasti menabrak sesuatu...",
  str_homestory_N23dianying_90030501_28_dialog_content = "A-Apa itu...?",
  str_homestory_N23dianying_90030501_29_dialog_content = "Aku tidak tahu. Sesuatu tampaknya telah dirobohkan.",
  str_homestory_N23dianying_90030501_30_dialog_content = "\"Satu boneka kecil, dua boneka kecil, tiga boneka kecil♪\"",
  str_homestory_N23dianying_90030501_S30_dialog_content = "A-Ahhhh!!!! I-Itu lagunya!",
  str_homestory_N23dianying_90030501_S31_dialog_content = "Ini...",
  str_homestory_N23dianying_90030501_31_dialog_content = "Ahhhh! Itu lagunya!",
  str_homestory_N23dianying_90030501_X31_dialog_content = "Whoaaa! Itu dia! Itu lagunya!",
  str_homestory_N23dianying_90030501_32_dialog_content = "\"Empat boneka kecil, lima boneka kecil, enam boneka kecil♪\"",
  str_homestory_N23dianying_90030501_S32_dialog_content = "A-Apa yang terjadi?",
  str_homestory_N23dianying_90030501_S33_dialog_content = "Jangan panik. Tetap tenang",
  str_homestory_N23dianying_90030501_33_dialog_content = "A-Apa yang terjadi?",
  str_homestory_N23dianying_90030501_34_dialog_content = "<color=#e8d9bb>Krak!</color>",
  str_homestory_N23dianying_90030501_35_dialog_content = "T-Lampunya baru saja padam!",
  str_homestory_N23dianying_90030501_36_dialog_content = "\"Tujuh boneka kecil, delapan boneka kecil, sembilan boneka kecil♪\"",
  str_homestory_N23dianying_90030501_X36_dialog_content = "Oh tidak. Ini semua salahku karena membuat film ini...",
  str_homestory_N23dianying_90030501_S36_dialog_content = "Anda, di mana saklar utama untuk lampu? Ceritakan sekarang!",
  str_homestory_N23dianying_90030501_37_dialog_content = "Ini semua karena film ini... Pasti dikutuk...",
  str_homestory_N23dianying_90030501_38_dialog_content = "\"Sembilan boneka kecil—dengan hanya delapan kepala kecil♪\"",
  str_homestory_N23dianying_90030501_39_dialog_content = "Heheh... Berani lihat?",
  str_homestory_N23dianying_90030601_1_dialog_content = "Nona Siobhan, persiapan untuk operasi khusus sudah selesai. Kita bisa mengambil tindakan kapan saja.",
  str_homestory_N23dianying_90030601_2_dialog_content = "Terima kasih! Sekarang kita tinggal menunggu Grand Marshal untuk melakukan latihan indoor iklan wajib militer bersama...",
  str_homestory_N23dianying_90030601_X1_dialog_content = "Komandan Vivian, persiapan untuk operasi khusus sudah selesai. Kita bisa mengambil tindakan kapan saja.",
  str_homestory_N23dianying_90030601_X2_dialog_content = "Kerja yang baik. Grand Marshal harus ada di sini kapan saja. Kami akan memulai latihan dalam ruangan dari iklan wajib militer segera setelah itu.",
  str_homestory_N23dianying_90030601_S1_dialog_content = "Komandan Barton, persiapan untuk operasi khusus sudah selesai. Kita bisa mengambil tindakan kapan saja.",
  str_homestory_N23dianying_90030601_S2_dialog_content = "Kerja yang baik. Grand Marshal akan ada di sini kapan saja. Kami akan memulai latihan dalam ruangan dari iklan wajib militer segera setelah itu.",
  str_homestory_N23dianying_90030601_3_dialog_content = "Maaf membuatmu menunggu, semuanya.",
  str_homestory_N23dianying_90030601_4_dialog_content = "Ini adalah upaya pertama saya dalam perekrutan inovatif semacam itu. Harap tetap semangat, dan bersama-sama, kami akan menunjukkan kepada dunia betapa gagahnya para prajurit Illumina!",
  str_homestory_N23dianying_90030601_5_dialog_content = "Siap, Pak!",
  str_homestory_N23dianying_90030601_6_dialog_content = "Saya berharap hari ini akan menjadi hari kelahiran kembali Anda.",
  str_homestory_N23dianying_90030601_7_dialog_content = "Anda masa lalu adalah di masa lalu. Yang penting adalah siapa Anda hari ini dan besok.",
  str_homestory_N23dianying_90030601_X7_dialog_content = "Apakah Anda memilih untuk meringkuk di sudut atau melangkah dan melawan?",
  str_homestory_N23dianying_90030601_X8_dialog_content = "Untuk memenuhi harapan, untuk menanggung kepercayaan rakyat, dan untuk menjawab doa-doa mereka?",
  str_homestory_N23dianying_90030601_X9_dialog_content = "Untuk menjadi berani dan tak kenal takut untuk orang yang kita cintai.",
  str_homestory_N23dianying_90030601_S7_dialog_content = "Apakah Anda membiarkan Eclipsites menghancurkan rumah Anda, atau apakah Anda bangkit dan melawan, bersumpah untuk merobek daging mereka bahkan hanya dengan gigi Anda?",
  str_homestory_N23dianying_90030601_S8_dialog_content = "Ingatlah apa yang telah mereka lakukan terhadap Anda, dan biarkan hal itu memicu kemarahan Anda.",
  str_homestory_N23dianying_90030601_S9_dialog_content = "Untuk masa depan semua Aurorian, dan kebebasan semua keturunan kita.",
  str_homestory_N23dianying_90030601_8_dialog_content = "Apakah Anda akan menyerah pada diri sendiri dan meringkuk di mana Anda berada atau menjelajahi dunia yang tidak dikenal dengan pasangan Anda?",
  str_homestory_N23dianying_90030601_9_dialog_content = "Jelajahi tanah yang hilang, atasi banyak rintangan, dapatkan teknologi berharga untuk melindungi masa depan Aurorian.",
  str_homestory_N23dianying_90030601_10_dialog_content = "Komitmen penuh Anda terhadap keputusan Anda berarti mengalami kelelahan dan rasa sakit hingga ke setiap tulang dan saraf Anda.",
  str_homestory_N23dianying_90030601_11_dialog_content = "Anda akan berguling-guling di lumpur sambil diteriaki oleh instruktur Anda. Pikiran dan tubuh Anda akan hancur sebelum ditempa kembali.",
  str_homestory_N23dianying_90030601_12_dialog_content = "Pelatihan akan tampak tanpa ampun dan brutal, tetapi kita semua tahu bahwa rasa hormat diperoleh di ujung tombak.",
  str_homestory_N23dianying_90030601_13_dialog_content = "Bekas luka yang Anda peroleh dari pelatihan adalah bukti tekad Anda.",
  str_homestory_N23dianying_90030601_14_dialog_content = "Kami mengawasi dalam kegelapan dan mengusir musuh yang berani mengganggu.",
  str_homestory_N23dianying_90030601_15_dialog_content = "Kemauan kita yang kuat akan membakar mereka, apakah mereka memiliki cakar yang tajam atau tubuh yang besar.",
  str_homestory_N23dianying_90030601_16_dialog_content = "Bergabunglah dengan kami, dan jadilah tulang dan daging legiun Illumina.",
  str_homestory_N23dianying_90030601_17_dialog_content = "Berjuang bersama saudara dan saudarimu yang mulia, dan rangkul dirimu yang baru.",
  str_homestory_N23dianying_90030601_18_dialog_content = "Berdiri bersama mereka dan pertahankan hak bertahan hidup semua Aurorian.",
  str_homestory_N23dianying_90030601_19_dialog_content = "Bersama-sama, Anda adalah tembok besar yang berdiri di antara medan perang yang tandus dan perapian Anda yang hangat.",
  str_homestory_N23dianying_90030601_20_dialog_content = "Aku, Reinhardt, Marsekal Agung Illumina, memerintahkan semua legiun Illumina...",
  str_homestory_N23dianying_90030601_21_dialog_content = "Pertahankan semua Aurorian dengan segala cara dan sampai mati.",
  str_homestory_N23dianying_90030601_22_dialog_content = "Jayalah Illumina!",
  str_homestory_N23dianying_90030601_23_dialog_content = "Kesempatan lotere gratis bagi siapa saja yang mengunjungi pusat perekrutan Illumina!",
  str_homestory_N23dianying_90030601_24_dialog_content = "Hadiahnya antara lain: Gram's Seasoned Can, Siobhan Autographed Photo, Philyshy's Comfort Expedition Bed, dan lain-lain!",
  str_homestory_N23dianying_90030601_25_dialog_content = "Ratusan rekrutan pertama yang beruntung juga akan menerima Voucher Pengalaman Pemandian Air Panas Pulau Cloud!",
  str_homestory_N23dianying_90030601_26_dialog_content = "Saya mengerti. Membawa hadiah untuk menarik perhatian adalah pendekatan yang diperlukan.",
  str_homestory_N23dianying_90030601_27_dialog_content = "Haruskah kita pergi ke pemandian air panas bersama setelah syuting iklan?",
  str_homestory_N23dianying_90030601_X26_dialog_content = "Kesempatan lotere gratis bagi siapa saja yang mengunjungi pusat perekrutan Illumina!",
  str_homestory_N23dianying_90030601_X27_dialog_content = "Hadiahnya antara lain: Gram's Seasoned Can, The Other End Experience Voucher, Succulent Plants Migard, dan lainnya!",
  str_homestory_N23dianying_90030601_X28_dialog_content = "Ratusan rekrutan pertama yang beruntung juga akan menerima Set Kegembiraan Sore!",
  str_homestory_N23dianying_90030601_X29_dialog_content = "Kami menunggu nama Anda di daftar rekrutmen!",
  str_homestory_N23dianying_90030601_S26_dialog_content = "Kesempatan lotere gratis bagi siapa saja yang mengunjungi pusat perekrutan Illumina!",
  str_homestory_N23dianying_90030601_S27_dialog_content = "Hadiahnya antara lain: Gram's Seasoned Can, Vida's Mine Detector Lollipop, Revy's Baseball Bat, dan lainnya!",
  str_homestory_N23dianying_90030601_S28_dialog_content = "Ratusan rekrutan pertama yang beruntung juga akan menerima Voucher Persahabatan Kapal Komandan Barton!",
  str_homestory_N23dianying_90030601_S29_dialog_content = "Betul sekali! Inilah peluang Anda!"
}
return config
